/** Feature flag overrides for internal users. This takes precendece over LiveShare.FeatureSet setting  */
const internalFeatures: vsls.FeatureFlagStore = {
    api: true,
    localUndo: false,
    localRedo: false,
    multiRootWorkspaceVSIDE: false,
    propagateFolderEvents: false,
    agentExtension: true
};

/** Feature flag overrides if 'LiveShare.FeatureSet' setting is 'Insiders'  */
const insidersFeatures: vsls.FeatureFlagStore = {
};

function isPrivateKey(key: Key): boolean {
    return privateSettings.indexOf(key) >= 0;
}

function isMementoKey(key: Key): boolean {
    return mementoSettings.indexOf(key) >= 0;
}

export type FeatureFlagInitializer = (featureFlags: vsls.FeatureFlagStore) => void | Promise<void>;

const featureFlagInitializers: FeatureFlagInitializer[] = [];
let featureFlagsInitialized = false;

export function registerFeatureFlagsInitializer(initializer: FeatureFlagInitializer) {
    if (featureFlagsInitialized) {
        throw Error('Feature flags are already initialzed');
    }

    featureFlagInitializers.push(initializer);
}

export async function initAsync(context: vscode.ExtensionContext): Promise<void> {
    await ic.InternalConfig.initAsync(context, Key[Key.userSettingsPath]);
    await MementoConfig.initAsync(context);

    const remoteSettingsUri = ic.InternalConfig.getUri(Key[Key.remoteSettingsUri]);
    if (remoteSettingsUri) {
        const updatePeriodInMinutes = ic.InternalConfig.get<number>(Key[Key.remoteSettingsUpdateMinutes]);
        await rc.RemoteConfig.initAsync(context, remoteSettingsUri, updatePeriodInMinutes);
    }

    // define the 'core' settings provider
    Settings.settingsProvider = {
        init(settingsContext: vscode.ExtensionContext) {
            return Promise.resolve();
        },
        get: (key) => get(key as Key),
        save: (key, value) => save(key as Key, value)
    };

    for (const initilizer of featureFlagInitializers) {
        const maybePromise = initilizer(featureFlags);
        if (maybePromise) {
            await maybePromise;
        }
    }

    featureFlagsInitialized = true;

    if (Settings.isInternalFeatureSet) {
        Object.assign(featureFlags, internalFeatures);
    } else if (Settings.isInsidersFeatureSet) {
        Object.assign(featureFlags, insidersFeatures);
    }

    Object.assign(featureFlags, get<vsls.FeatureFlagStore>(Key.experimentalFeatures));

    // Add defined feature flags to vscode command context
    for (const flag in featureFlags) {
        if (featureFlags.hasOwnProperty(flag)) {
            const flagValue = (<any>featureFlags)[flag];
            if (typeof flagValue !== 'undefined' && flagValue !== null) {
                vscode.commands.executeCommand('setContext', `liveshare:feature:${flag}`, flagValue);
            }
        }
    }

    await vscode.commands.executeCommand('setContext', CommandContext.isTeamMember, isVSLSTeamMember());
    await vscode.commands.executeCommand('setContext', CommandContext.vscodeAccountAuthEnabled, Settings.isVSCodeAccountAuth);
    await vscode.commands.executeCommand('setContext', CommandContext.isNativeAuthEnabled, Settings.isNativeAuth);
}

export function waitForRemoteUpdateAsync(): Promise<void> {
    return rc.RemoteConfig.waitForUpdateAsync();
}

export function save(key: Key, value: any, global: boolean = true, delaySaveToDisk = false): Thenable<void> {
    if (isPrivateKey(key)) {
        return ic.InternalConfig.save(key, value, delaySaveToDisk);
    }

    if (isMementoKey(key)) {
        return MementoConfig.save(key, value);
    }

    const extensionConfig = vscode.workspace.getConfiguration(get<string>(Key.configName));

    if (global && value === undefined) {
        const currentValues = extensionConfig.inspect(key);
        if (!currentValues || currentValues.globalValue === undefined) {
            // Trying to remove a global value that doesn't exist, so there's nothing to do.
            return Promise.resolve();
        }
    }

    return extensionConfig.update(key, value, global);
}

export function get<T>(key: Key): T | undefined {
    const remoteOverrideValue = rc.RemoteConfig.getOverride<T>(key);
    if (remoteOverrideValue !== undefined) {
        // Remote overrides, when set, override any internal or user setting.
        return remoteOverrideValue;
    }

    if (isPrivateKey(key) || isMementoKey(key)) {
        const value = ic.InternalConfig.get(key) as T;
        if (value === undefined && isMementoKey(key)) {
            return MementoConfig.get(key);
        }

        return value;
    }

    const entepriseOverridenValue = ec.EnterpriseConfig.get<T>(key);
    if (entepriseOverridenValue !== undefined) {
        return entepriseOverridenValue;
    }

    const extensionConfig = vscode.workspace.getConfiguration(get<string>(Key.configName));

    const remoteDefaultValue = rc.RemoteConfig.getDefault<T>(key);
    if (remoteDefaultValue !== undefined) {
        // Remote defaults, when set, are used as the default value instead of the
        // default value declared in the extension package. The default substitution
        // is achieved by using inspect() instead of get().
        const setting = extensionConfig.inspect<T>(key);
        if (setting) {
            if (setting.workspaceFolderValue !== undefined) {
                return setting.workspaceFolderValue;
            } else if (setting.workspaceValue !== undefined) {
                return setting.workspaceValue;
            } else if (setting.globalValue !== undefined) {
                return setting.globalValue;
            }
            // setting.defaultValue is not used in this case.
        }
        return remoteDefaultValue;
    } else {
        // Use the value from normal VS Code workspace, global, or default settings.
        return extensionConfig.get<T>(key);
    }
}

export function getUserSettings(): vsls.UserSettings {
    const userSettings = ic.InternalConfig.getUserSettings();
    userSettings.experimentalFeatures = featureFlags;
    userSettings.increasedGuestLimit = get(Key.increasedGuestLimit);
    userSettings.syncRpcTelemetryTresholdMs = get(Key.syncRpcTelemetryTresholdMs);
    return userSettings;
}

export function getUri(key: Key): url.Url | undefined {
    if (isPrivateKey(key)) {
        return ic.InternalConfig.getUri(key);
    }
    if (isMementoKey(key)) {
        return MementoConfig.getUri(key);
    }
    let value = get<string>(key);
    if (!value) {
        return undefined;
    }

    try {
        return url.parse(value);
    } catch (e) {
        return undefined;
    }
}

export function getClientCapabilties(): vsls.ClientCapabilities {
    return {
        extensionReadOnlySupport: true,
        clientReadOnlySupport: semver.gte(semver.coerce(vscode.version)!, '1.25.1'),
        emptyWorkspaceOpenFolderSupport: false
    };
}

export function isVSLSTeamMember(): boolean {
    return !!get<string>(Key.teamStatus);
}

export const isVSCodeAccountAuthSupported = (): boolean => {
    // if no API supported, disable the new auth flow since it relies on the APIs
    const unknowApi = vscode.env as any;

    const isCreateAppUri = isFunction(unknowApi.createAppUri);
    const isAsExternalUri = !!(isFunction(unknowApi.asExternalUri) && vscode.env.uriScheme);
    
    return !!((isCreateAppUri || isAsExternalUri) && isFunction(unknowApi.openExternal));
};

export const isMacOSxCatalinaOrNewer = (): boolean => {
    const platform = os.platform();
    const majorVersion = parseInt(os.release().split('.')[0], 10);

    return (platform === 'darwin' && majorVersion >= 19);
};

export const ensureVSCodeAccountAuthFlow = async () => {
    const currentFlag = get(Key.isVSCodeAccountAuthEnabled);

    if (typeof currentFlag === 'boolean') {
        return;
    }

    return await save(Key.isVSCodeAccountAuthEnabled, true);
};

export const isVSCodeAccountAuthDisabled = (): boolean => {
    return (get(Key.isVSCodeAccountAuthEnabled) === false);
};

export const wasDownloadCorrupted = (): boolean => {
    return (get(Key.wasDownloadCorrupted) === true);
};

export const isCITestTeamStatus = () => {
    const teamStatus: string = (get(Key.teamStatus) || '');

    return (teamStatus.toLowerCase() === 'citest');
};

/**
 * Return true if presence settings is enabled
 */
export const isLivesharePresenceEnabled = (): boolean => {
    return get<boolean>(Key.presence) === true;
};

/**
 * Return true if the signalR Uri was defined
 */
export const isLivesharePresenceProviderEnabled = (): boolean =>  {
    return getUri(Key.signalRServiceUri) !== undefined;
};

export async function resetMementoValues(): Promise<void> {
    for (const key of mementoSettings) {
        await save(key, undefined);
    }
}

export async function getMementoValues(): Promise<Map<Key, any>> {
    const values = new Map<Key, any>();
    for (const key of mementoSettings) {
        const value = await get(key);
        values.set(key, value);
    }

    return values;
}

export async function reloadSettingsFile(): Promise<void> {
    return ic.InternalConfig.readUserSettings(Key[Key.userSettingsPath]);
}
