import * as vscode from 'vscode';

import { CommandId } from '@vs/liveshare-core';
import { AgentRpcClient } from '../../workspace/AgentRpcClient';
import {
    lazyLoad,
    MementoConfig
} from '@vs/liveshare-core';
import { IRPCClient } from '../IRPCClient';

export const rpcClientFactory = lazyLoad<IRPCClient>(() => {
    const settings = vscode.workspace.getConfiguration();
    const workspaceId = settings.get(CommandId.joinWorkspaceIdSettingName);
    let rpcConnectId: string = null;
    if (workspaceId) {
        const keyReconnectionId = workspaceId.toString() + '-reconnectId';
        rpcConnectId = MementoConfig.get<string>(keyReconnectionId);
        if (rpcConnectId) {
            MementoConfig.save(keyReconnectionId, null);
        }
    }
    return new AgentRpcClient(rpcConnectId);
});
