import * as vscode from 'vscode';
import { vsls } from '@vs/liveshare-core';
import { IWorkspaceEnvironmentUtil } from './IWorkspaceEnvironmentUtil';

export interface IVsCodeShareInfo {
    foundUnsupportedSchemes: boolean;
    shareInfo: vsls.WorkspaceShareInfo;
}

/**
 * Helper functions for working with VS Code workspaces.
 */
export class WorkspaceEnvironmentUtil implements IWorkspaceEnvironmentUtil {
    public getAllRootFileSystemPaths(): { foundUnsupportedSchemes: boolean; paths: string[] } {
        let foundUnsupportedSchemes = false;
        const paths = vscode.workspace.workspaceFolders == null ?
        [ null ] :
        vscode.workspace.workspaceFolders.map((folder) => {
            if (folder.uri.scheme.toLowerCase() !== 'file') {
                foundUnsupportedSchemes = true;
                return null;
            }

            return folder.uri.fsPath;
        });

        return {
            foundUnsupportedSchemes: foundUnsupportedSchemes,
            paths: paths,
        };
    }

    public isWebviewSupported(): boolean {
        const window: any = vscode.window;
        return (typeof window.createWebviewPanel) === 'function';
    }
}