'use strict';

import * as vscode from 'vscode';
import * as path from 'path';
import * as os from 'os';
import * as net from 'net';
import * as uuid from 'uuid';

import * as config from '../config';
import { vsls, SettingKeys, Settings, ExtensionUtil as ExtensionUtilCore, CommandContext } from '@vs/liveshare-core';
import { RpcProxy } from '@vs/vso-rpc';
import { OSPlatform, getPlatformProperty } from '@vs/vso-node-utils';
import { traceSource, IDataScrapingWorker, Disposable, Inittable, createTerminalRenderer } from '@vs/vscode-command-framework';
import { TerminalControllerBase, tt } from '@vs/liveshare-terminals';

import { Lazy } from '../_new_/abstractions/Interfaces';
import { IDependencies } from '../_new_/IDependencies';
import { INotificationUtil } from '../_new_/abstractions/INotificationUtil';
import { READ_ONLY_LABEL } from '../constants';

import { getPipePath } from '@vs/vso-node-utils';
import { createTerminalEndpointBufferFactory } from './terminalEndpointBufferFactory';
import {
    Telemetry,
    FaultType
} from '@vs/vso-telemetry';

import {
    PathUtil,
    SessionContext,
    WellKnownRestrictedOperations,
    TelemetryEventNames,
    TelemetryPropertyNames,
    workspaceSessionInfoTracker,
    commandBindingDecorator,
    ControllerHelper,
    IWorkspaceAccessControlManager
} from '@vs/liveshare-core';

/**
 * Starts observing terminal output and extracting metadata from written data.
 * Updates shared terminal cache when altering terminal property values.
 */
class UserPromptScraper extends Inittable(Disposable(Object)) implements IDataScrapingWorker {
    constructor(private readonly terminalEntry: tt.TerminalEntry) { super(); }

    public processData(data: string): void {
        const from = data.lastIndexOf('\r');
        if (from !== -1) {
            // set new prompt
            this.terminalEntry.update(tt.MetadataKey.prompt, data.substr(from));
        } else {
            // append this data block to the current prompt
            const current = this.terminalEntry.get(tt.MetadataKey.prompt) || '';
            this.terminalEntry.update(tt.MetadataKey.prompt, current.concat(data));
        }
    }
}

export interface IHostTerminalController extends TerminalControllerBase { }

export const hostTerminalControllerFactory = (deps: IDependencies) => {
    const {
        controllerDecorator,
        telemetryMethodDecorator,
        errorNotificationMethodDecorator
    } = deps.methodDecorators();

    /**
     * Registers and handles VSCode commands controlling shared terminal behavior in a shared collaboration session.
     */
    @controllerDecorator
    class HostTerminalController extends TerminalControllerBase implements IHostTerminalController {
        private readonly notificationUtil: INotificationUtil;
        private readonly workspaceAccessControlManager: Lazy<IWorkspaceAccessControlManager>;
        private dataScraper: vscode.Disposable | undefined;
        private readonly workspaceAccessControlService: Lazy<vsls.WorkspaceAccessControlService>;

        constructor(dependencies: IDependencies) {
            super(dependencies.terminalService(), createTerminalEndpointBufferFactory(), traceSource.withName('HostTerminalController'));
            this.notificationUtil = dependencies.notificationUtil();
            this.workspaceAccessControlManager = dependencies.workspaceAccessControlManager;
            this.workspaceAccessControlService = dependencies.workspaceAccessControlService;

            if (config.get(config.Key.autoShareTerminals)) {
                this.deferWork(() => this.launchDataScraper(dependencies));
            }
        }

        public async dispose(): Promise<void> {
            if (this.dataScraper) {
                this.dataScraper.dispose();
            }

            await super.dispose();
        }

        public async activate(): Promise<boolean> {
            if (this.isActivated) {
                return true;
            }

            await super.activate();

            ControllerHelper.register(this, this.sessionSubscriptions);

            this.workspaceAccessControlService().onOpeationAccessRequested(e => {
                if (SessionContext.isCollaborating &&
                    e.operation.name === WellKnownRestrictedOperations.WriteToSharedTerminal) {
                    this.requestOperationAccess(e.operation, e.sessionId);
                }
            });

            // enable auto-share terminals
            if (config.get(config.Key.autoShareTerminals) &&
                vscode.window.onDidOpenTerminal
            ) {
                vscode.window.onDidOpenTerminal(
                    async terminal => {
                        if (!tt.isTaskTerminal(terminal) &&
                            !tt.isSharedTerminal(terminal)
                        ) {
                            await this.shareTerminalInternal(terminal);
                        }
                    },
                    this,
                    this.sessionSubscriptions
                );

                this.deferredWork = this.deferredWork
                    .then(async () => {
                        await Promise.all(
                            vscode.window.terminals
                                .filter(x => !tt.isTaskTerminal(x) && !tt.isSharedTerminal(x))
                                .map(x => this.shareTerminalInternal(x))
                        );
                    })
                    .catch(reason => {
                        this.trace.error(reason.message);
                    });
            }

            let allowReadWriteTerminals = Settings.get<boolean>(SettingKeys.allowReadWriteTerminals);
            ExtensionUtilCore.setCommandContext(
                CommandContext.readOnlyTerminalsEnforced,
                (allowReadWriteTerminals !== undefined) ? !allowReadWriteTerminals : false
            );

            return true;
        }

        /**
         * Shares an existing terminal window by starting a terminal worker that synchronizes i/o data streams
         * with collaboration session participants.
         *
         * @param terminal Existing terminal window.
         */
        private async shareTerminalInternal(terminal: vscode.Terminal): Promise<void> {
            const terminalEntry = this.terminalCache.get(terminal);
            const prompt = terminalEntry ? terminalEntry.get(tt.MetadataKey.prompt) : null;

            const dataPipeName = uuid().replace(/-/g, '');
            const dimensions = {
                columns: config.get<number>(config.Key.sharedTerminalWidth),
                rows: config.get<number>(config.Key.sharedTerminalWidth)
            };
            const options: vsls.TerminalOptions = {
                name: (terminal.name || 'terminal') + ' [Shared]', // Workaround for https://github.com/Microsoft/vscode/issues/53057 where terminal.name may be null sometimes.
                dataPipeName: dataPipeName,
                rows: dimensions.rows,
                cols: dimensions.columns,
                readOnlyForGuests: true,
            };

            let terminalInfo: vsls.TerminalInfo = null;
            let dataServer: net.Server = null;
            let registrations: vscode.Disposable[] = [];
            let writeDataQueue: Promise<void> = Promise.resolve();

            try {
                dataServer = net.createServer((socket) => {
                    if (typeof vscode.window.onDidWriteTerminalData === 'function') {
                        vscode.window.onDidWriteTerminalData((e) => {
                                if (e.terminal === terminal) {
                                    const s = e.data;
                                    writeDataQueue = writeDataQueue.then(
                                        async () => {
                                            await socket.write(s);
                                        });
                                }
                            }, 
                            null /* this */, 
                            registrations);
                    } else {
                        terminal.onDidWriteData(s => writeDataQueue = writeDataQueue.then(
                            async () => {
                                await socket.write(s);
                            }),
                            null /* this */,
                            registrations);
                    }
                    socket.on('data', (data: Buffer) => {
                        terminal.sendText(data.toString(), false /* addNewLine */);
                    });
                    socket.on('error', (err: Error) => {
                        this.trace.error(err.message);
                    });
                    if (prompt) {
                        socket.write(prompt);
                    }
                }).listen(getPipePath(dataPipeName));

                terminalInfo = await this.terminalService.startTerminalAsync(options);
            } catch (e) {
                this.trace.error(`Error running a shared terminal worker. ${e}`);
                Telemetry.sendFault(TelemetryEventNames.RUN_SHARED_TERMINAL_FAULT, FaultType.Error, null, e);

                if (dataServer) {
                    dataServer.close();
                }
                return;
            }

            this.terminalService.onTerminalStopped(
                (e: vsls.TerminalEventArgs) => {
                    if (e.terminal.id === terminalInfo.id) {
                        disposeTerminalWorker();
                    }
                },
                null /* this */,
                registrations
            );

            const disposeTerminalWorker = async (shouldStopTerminal?: boolean) => {
                registrations.forEach(d => d.dispose());
                try {
                    if (shouldStopTerminal &&
                        !(<RpcProxy><any>this.terminalService).client.isDisposed
                    ) {
                        await this.terminalService.stopTerminalAsync(terminalInfo.id);
                    }
                } catch { }
                try {
                    dataServer.close();
                } catch { }
            };

            this.terminalCache.register(
                terminal,
                terminalInfo.id,
                false /* own */,
                {
                    dispose: () => disposeTerminalWorker(true /* shouldStopTerminal */),
                }
            );

            Telemetry.sendTelemetryEvent(TelemetryEventNames.SHARE_TERMINAL, {
                [TelemetryPropertyNames.SHARED_TERMINAL_READONLY]: false.toString(),
            });
        }

        private async launchDataScraper(dependencies: IDependencies) {
            this.dataScraper = await dependencies.dataScrapingManager().registerDataScraper('user-prompt-scraper', terminal => {
                if (tt.isTaskTerminal(terminal) || tt.isSharedTerminal(terminal)) {
                    return null;
                }
                const terminalEntry = this.terminalCache.register(terminal);
                return new UserPromptScraper(terminalEntry);
            });
        }

        private async requestOperationAccess(operation: vsls.RestrictedOperation, sessionId: number): Promise<void> {
            try {
                const response = await this.requestReadWriteAccessForTerminal((<any>operation).terminalId, sessionId);

                if (typeof response === 'boolean') {
                    await this.workspaceAccessControlService().setOperationAccessAsync(
                        operation,
                        response ? vsls.RestrictedOperationAccess.Allowed : vsls.RestrictedOperationAccess.ExplicitlyRejectedByHost);
                }

            } catch (err) {
                const message = `Requesting access for '${operation ? operation.name : 'null'}' operation failed: ${err.message}`;
                this.trace.error(message);
                Telemetry.sendFault(TelemetryEventNames.REQUEST_OPERATION_ACCESS_FAULT, FaultType.NonBlockingFault, message, err);
            }
        }

        public async requestReadWriteAccessForTerminal(terminalId: number, sessionId: number): Promise<boolean | undefined> {
            const terminal: vsls.TerminalInfo = (await this.terminalService.getRunningTerminalsAsync()).find(t => t.id === terminalId);
            const participant = SessionContext.collaboratorManager.getCollaborators()[sessionId.toString(10)];
            if (!terminal || !participant) {
                return undefined;
            }

            const allow = 'Make the terminal read/write for everyone';
            const reject = 'Keep it read-only';
            const response = await this.notificationUtil.showInformationMessage(
                `${participant.name} requested permission to write to the '${terminal.options.name}' terminal`, false,
                { modal: false },
                allow, reject);

            if (response === allow) {
                await this.setTerminalReadOnly(terminalId, false);
                return undefined;
            }

            return response === reject ? false : undefined;
        }

        @errorNotificationMethodDecorator('Removing Terminal', TelemetryEventNames.REMOVE_TERMINAL_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.REMOVE_TERMINAL, TelemetryEventNames.REMOVE_TERMINAL_FAULT, 'RemoveTerminal')
        @commandBindingDecorator('liveshare.fileTreeExplorer.removeTerminal')
        @commandBindingDecorator('liveshare.activityBar.removeTerminal')
        private async closeTerminal(terminalPayload?: tt.IViewItemTerminalPayload | undefined): Promise<boolean> {
            if (!terminalPayload) {
                return false;
            }

            const terminals: vsls.TerminalInfo[] = await this.terminalService.getRunningTerminalsAsync();
            for (const terminalInfo of terminals.filter(t => t.id === terminalPayload.terminalId)) {
                await this.terminalService.stopTerminalAsync(terminalInfo.id);
                break;
            }
            return true;
        }

        @errorNotificationMethodDecorator('Making Terminal Read-Only', TelemetryEventNames.MAKE_TERMINAL_READ_ONLY_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.MAKE_TERMINAL_READ_ONLY, TelemetryEventNames.MAKE_TERMINAL_READ_ONLY_FAULT, 'MakeTerminalReadOnly')
        @commandBindingDecorator('liveshare.fileTreeExplorer.makeTerminalReadOnly')
        @commandBindingDecorator('liveshare.activityBar.makeTerminalReadOnly')
        private async makeTerminalReadOnly(terminalPayload?: tt.IViewItemTerminalPayload | undefined): Promise<boolean> {
            if (!terminalPayload) {
                return false;
            }

            return await this.setTerminalReadOnly(terminalPayload.terminalId, true /* isReadOnly */);
        }

        @errorNotificationMethodDecorator('Making Terminal Read/Write', TelemetryEventNames.MAKE_TERMINAL_READ_WRITE_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.MAKE_TERMINAL_READ_WRITE, TelemetryEventNames.MAKE_TERMINAL_READ_WRITE_FAULT, 'MakeTerminalReadWrite')
        @commandBindingDecorator('liveshare.fileTreeExplorer.makeTerminalReadWrite')
        @commandBindingDecorator('liveshare.activityBar.makeTerminalReadWrite')
        private async makeTerminalReadWrite(terminalPayload?: tt.IViewItemTerminalPayload | undefined): Promise<boolean> {
            if (!terminalPayload) {
                return false;
            }

            return await this.setTerminalReadOnly(terminalPayload.terminalId, false /* isReadOnly */);
        }

        private async setTerminalReadOnly(terminalId: number, isReadOnly: boolean): Promise<boolean> {
            const terminals: vsls.TerminalInfo[] = await this.terminalService.getRunningTerminalsAsync();
            for (const terminalInfo of terminals.filter(t => t.id === terminalId)) {
                await this.terminalService.setTerminalReadOnlyForGuestsAsync(terminalInfo.id, isReadOnly);
                await this.workspaceAccessControlManager().setOperationAccess(
                    <any>{ name: WellKnownRestrictedOperations.WriteToSharedTerminal, terminalId },
                    isReadOnly ? vsls.RestrictedOperationAccess.DisabledByHostConfiguration : vsls.RestrictedOperationAccess.Allowed);
                break;
            }
            return true;
        }

        @errorNotificationMethodDecorator('Sharing Terminal', TelemetryEventNames.SHARE_TERMINAL_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.SHARE_TERMINAL, TelemetryEventNames.SHARE_TERMINAL_FAULT, 'ShareTerminal')
        @commandBindingDecorator('liveshare.shareTerminal')
        @commandBindingDecorator('liveshare.fileTreeExplorer.shareTerminal')
        @commandBindingDecorator('liveshare.activityBar.shareTerminal')
        private async shareTerminal(): Promise<boolean> {
            try {
                // In read-only session the shared terminal is always read-only.
                // In regular session, query the host if they want it read-write or read-only.
                let guestsCanWriteChoice = READ_ONLY_LABEL;

                let allowReadWriteTerminals = Settings.get<boolean>(SettingKeys.allowReadWriteTerminals);
                if (!workspaceSessionInfoTracker.isReadOnly && (allowReadWriteTerminals !== undefined) ? allowReadWriteTerminals : true) {
                    guestsCanWriteChoice = await this.notificationUtil.showQuickPick(
                        [READ_ONLY_LABEL, 'Read/write'], { placeHolder: 'Select the access level guests should have for this terminal' });
                    if (guestsCanWriteChoice === undefined) {
                        return;
                    }
                }

                const cfg = vscode.workspace.getConfiguration();
                const configShellProperty = `terminal.integrated.shell.${getPlatformProperty()}`;
                const configShell = cfg.get<string>(configShellProperty) || (os.platform() === OSPlatform.WINDOWS ? 'powershell' : 'bash');

                const shellBasename = path.basename(configShell).toLowerCase();

                // Use 'ps' to shorten the terminal name for powershell. The terminal name lengh is limited by the terminal drop down width in VSCode.
                const name: string = `${shellBasename === 'powershell.exe' ? 'ps' : path.basename(shellBasename, path.extname(shellBasename))} [Shared]`;

                // If terminal renderer is supported, spin it to get the dimensions
                let dimensions: vscode.TerminalDimensions;
                const renderer: vscode.TerminalRenderer = createTerminalRenderer(name);
                if (renderer) {
                    const dimensionsPromise = new Promise<vscode.TerminalDimensions>((resolve) => {
                        if (renderer.maximumDimensions) {
                            resolve(renderer.maximumDimensions);
                        } else {
                            const eventRegistration = renderer.onDidChangeMaximumDimensions(e => {
                                eventRegistration.dispose();
                                resolve(e);
                            });
                        }
                    });

                    // tslint:disable-next-line:no-shadowed-variable
                    const terminal = await renderer.terminal;
                    await terminal.show();
                    dimensions = await dimensionsPromise;
                } else {
                    dimensions = {
                        columns: config.get<number>(config.Key.sharedTerminalWidth),
                        rows: config.get<number>(config.Key.sharedTerminalWidth)
                    };
                }

                const configArgs = cfg.get<string[]>(`terminal.integrated.shellArgs.${getPlatformProperty()}`) || [];
                const configEnv = cfg.get<{ [key: string]: string; }>(`terminal.integrated.env.${getPlatformProperty()}`);
                const readOnlyForGuests = (guestsCanWriteChoice === READ_ONLY_LABEL);
                let options: vsls.TerminalOptions = {
                    name,
                    rows: dimensions.rows,
                    cols: dimensions.columns,
                    cwd: cfg.get<string>('terminal.integrated.cwd') || PathUtil.getPrimaryWorkspaceFileSystemPath() || os.homedir(),
                    app: configShell,
                    commandLine: configArgs,
                    environment: configEnv,
                    readOnlyForGuests,
                };

                const terminalInfo: vsls.TerminalInfo = await this.terminalService.startTerminalAsync(options);

                await this.createTerminal(terminalInfo, renderer);

                Telemetry.sendTelemetryEvent(TelemetryEventNames.SHARE_TERMINAL, {
                    [TelemetryPropertyNames.SHARED_TERMINAL_SHELL]: path.parse(configShell).name,
                    [TelemetryPropertyNames.SHARED_TERMINAL_READONLY]: readOnlyForGuests.toString(),
                });
            } catch (e) {
                Telemetry.sendFault(TelemetryEventNames.SHARE_TERMINAL_FAULT, FaultType.Error, null, e);
                throw e;
            }
            return true;
        }

        @errorNotificationMethodDecorator('Opening Terminal', TelemetryEventNames.OPEN_TERMINAL_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.OPEN_TERMINAL, TelemetryEventNames.OPEN_TERMINAL_FAULT, 'OpenTerminal')
        @commandBindingDecorator('liveshare.fileTreeExplorer.openTerminal')
        @commandBindingDecorator('liveshare.activityBar.openTerminal')
        private async openTerminal(terminalPayload?: tt.IViewItemTerminalPayload | undefined): Promise<boolean> {
            if (!terminalPayload) {
                return false;
            }

            const terminals: vsls.TerminalInfo[] = await this.terminalService.getRunningTerminalsAsync();

            for (const terminalInfo of terminals.filter(t => t.id === terminalPayload.terminalId)) {
                await this.createTerminal(terminalInfo);
                break;
            }
            return true;
        }
    }

    return new HostTerminalController(deps);
};
