export const renderCircleIcon = (color: string, isFilled: boolean = false): string => {
    return `
        <svg xmlns="http://www.w3.org/2000/svg">
            <!--
                SVG inside SVG is because VSCode ignores the width / height on the root
                element. So nesting it lets us use the width/height to scale it. The
                x/y are to reposition it to be centered.
            -->
            <svg width="16px" height="16px" viewBox="0 0 16 16" version="1.1">
                <circle id="filled" fill="${color}" fill-rule="nonzero" cx="8" cy="8" r="${(isFilled) ? 6 : 0}"></circle>
                <path d="M8,14 C4.6862915,14 2,11.3137085 2,8 C2,4.6862915 4.6862915,2 8,2 C11.3137085,2 14,4.6862915 14,8 C14,11.3137085 11.3137085,14 8,14 Z M8,12 C10.209139,12 12,10.209139 12,8 C12,5.790861 10.209139,4 8,4 C5.790861,4 4,5.790861 4,8 C4,10.209139 5.790861,12 8,12 Z" id="stroke" fill="${color}" fill-rule="nonzero"></path>
            </svg>
        </svg>
    `;
};