import * as vscode from 'vscode';
import { fileAccess } from '@vs/vscode-command-framework';
import * as path from 'path';
import * as uuid from 'uuid';

import { EXTENSION_ROOT_PATH } from '../constants';

import {
    SessionAction,
    SessionState,

} from '@vs/liveshare-core';

export default class WelcomePageHTMLProvider implements vscode.TextDocumentContentProvider {
    public isWebview: boolean;
    public isFirstTimeJoin: boolean;
    public isPostReloadJoin: boolean;
    public isAuthenticated: boolean;
    public joinUri: string;
    public sessionState: SessionState;
    public sessionHigherState: SessionState;
    public sessionAction: SessionAction;
    public hasCollaborators: boolean;

    private readonly onDidChangeInternal: vscode.EventEmitter<vscode.Uri> = new vscode.EventEmitter<vscode.Uri>();
    
    public readonly onDidChange: vscode.Event<vscode.Uri> = this.onDidChangeInternal.event;

    public update(uri: vscode.Uri) {
        this.onDidChangeInternal.fire(uri);
    }

    public provideTextDocumentContent(uri: vscode.Uri): string {
        const extensionDir = path.resolve(EXTENSION_ROOT_PATH, './out/prod');
        const welcomePageDir = path.join(extensionDir, './welcomePage/');
        const mainScriptPath = vscode.Uri.file(path.join(welcomePageDir, 'welcomePageMain.js'));
        const stylePath = vscode.Uri.file(path.join(welcomePageDir, 'welcomePage.css'));
        let contents = fileAccess.readFileSync(path.join(welcomePageDir, 'welcomePage.html')).toString();

        // Create a nonce to whitelist which scripts & styles can be run
        const nonce = this.getNonce();
        const initializeScriptBlock = `<script nonce="${nonce}">const vslsCurrentSessionState=${this.sessionState}; vslsCurrentSessionHigherState=${this.sessionHigherState}; 
        vslsCurrentSessionAction=${this.sessionAction}; const vslsIsWebView=${this.isWebview}; const vslsIsFirstTimeJoin=${this.isFirstTimeJoin}; 
        const vslsIsPostReloadJoin = ${this.isPostReloadJoin}; const vslsSessionState=${JSON.stringify(SessionState)}; const vslsSessionAction=${JSON.stringify(SessionAction)}; 
        const vslsIsAuthenticated=${this.isAuthenticated};
        const hasCollaborators=${this.hasCollaborators};</script>`;
        if (this.isWebview) {
            const mainScriptUri = mainScriptPath.with({ scheme: 'vscode-resource' });
            const styleUri = stylePath.with({ scheme: 'vscode-resource' });
            contents = contents.replace('${mainScriptUri}', mainScriptUri.toString())
                .replace('${styleUri}', styleUri.toString());
        } else {
            // For HTML preview embed the script & styles in the page
            const mainScriptContents = fileAccess.readFileSync(mainScriptPath.fsPath);
            const styleContents = fileAccess.readFileSync(stylePath.fsPath);
            contents = contents.replace('<script nonce="${nonce}" src="${mainScriptUri}"></script>', `<script nonce="${nonce}">${mainScriptContents}</script>`)
                .replace('<link rel="stylesheet" href="${styleUri}" nonce="${nonce}">', `<style nonce="${nonce}">${styleContents}</style>`);
        }

        return contents.replace(/\$\{this.joinUri\}/g, this.joinUri)
            .replace('<script nonce="${nonce}"></script>', initializeScriptBlock)
            .replace(/\$\{nonce\}/g, nonce);
    }

    private getNonce() {
        return uuid().replace(/-/g, '');
    }
}