import * as vscode from 'vscode';
import { dependencies } from '../_new_/Dependencies';
import { ViewItem } from '@vs/liveshare-api';
import {
     ISessionContext,
    SessionExplorerProvider,
    ParticipantsTreeDataProvider,
    TerminalsTreeDataProvider,
    ServerSharingTreeDataProvider,
    ExtensionUtil,
    IContactManager,
    IClientAccessCheck,
    Lazy,
    TreeViewItem
} from '@vs/liveshare-core';
import { TraceSource } from '@vs/vso-logging';
import { ContactManager } from '@vs/liveshare-contactservice';

import { CommentsTreeDataProvider } from '@vs/liveshare-reviews';
import { CollabActionTreeDataProvider } from './CollabActionTreeDataProvider';
import { userIconProvider } from './UserIconsProvider';
import { ChatTreeDataProvider, CommunicationsManager } from '@vs/liveshare-communications';

export enum SessionExplorerType {
    ViewletInActivityBar = 'ActivityBar',
    ViewletInFileExplorer = 'SessionExplorer',
}

export async function createSessionExplorer(
    sessionContext: ISessionContext, 
    showCollabActions: boolean,
    initiator: SessionExplorerType, 
    trace: TraceSource): Promise<SessionExplorerProvider> {

    const isSessionExplorer = initiator === SessionExplorerType.ViewletInFileExplorer;
    const sessionExplorerProvider = new SessionExplorerProvider(sessionContext);

    // collab actions
    const collabActionTreeDataProvider = new CollabActionTreeDataProvider(isSessionExplorer);
    if (showCollabActions) {
        sessionExplorerProvider.registerTreeDataProvider(collabActionTreeDataProvider);
    }

    // participants
    const participantsTreeDataProvider = new CustomParticipantsTreeDataProvider(
        sessionContext,
        dependencies.clientAccessCheck,
        ContactManager,
        isSessionExplorer);
    sessionExplorerProvider.registerTreeDataProvider(participantsTreeDataProvider);
    
    // shared servers
    const serverSharingTreeDataProvider = new ServerSharingTreeDataProvider(
        sessionContext,
        isSessionExplorer,
        trace);
    sessionExplorerProvider.registerTreeDataProvider(serverSharingTreeDataProvider);

    // terminals
    const terminalsTreeDataProvider = new TerminalsTreeDataProvider(
        sessionContext,
        isSessionExplorer,
        trace);
    sessionExplorerProvider.registerTreeDataProvider(terminalsTreeDataProvider);
 
    // comments
    const commentsTreeDataProvider = new CommentsTreeDataProvider();
    sessionExplorerProvider.registerTreeDataProvider(commentsTreeDataProvider);

    // chat
    const isChatEnabled = await CommunicationsManager.isChatEnabled();
    if (isChatEnabled) {
        const chatTreeDataProvider = new ChatTreeDataProvider();
        sessionExplorerProvider.registerTreeDataProvider(chatTreeDataProvider);
    }

    return sessionExplorerProvider;
}

class CustomParticipantsTreeDataProvider extends ParticipantsTreeDataProvider {  
    constructor(
        sessionContext: ISessionContext,
        clientAccessCheck: Lazy<IClientAccessCheck>,
        contactManager: IContactManager,
        isSessionExplorer: boolean) {
            super(sessionContext, clientAccessCheck, contactManager, isSessionExplorer);
    }

    protected getDefaultParticipantsActions(): TreeViewItem[] {
        return [
            new TreeViewItem({
                type: ViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: 'Invite participants...',
                command: {
                    title: 'Invite participants...',
                    command: (this.isSessionExplorer)
                        ? 'liveshare.collaboration.link.copyFromFileTreeExplorer'
                        : 'liveshare.collaboration.link.copyFromActivityBar'
                }
            })
        ];
    }

    protected async getIconPathForUser(rowIndex: number, userId: number, isFollowing: boolean): Promise<any> {
        const iconBundle = await userIconProvider.getIconByUserId(userId);
        let iconPath;
        if (iconBundle) {
            const iconPathBundle = isFollowing ?
                iconBundle.filled
                : iconBundle.normal;
            iconPath = {
                dark: iconPathBundle,
                light: iconPathBundle
            };
        }

        return iconPath;
    }
}