import * as vscode from 'vscode';

import { ICommandContext } from '@vs/vscode-command-framework';

import { vsls } from '@vs/liveshare-core';

import { IDependencies } from '../IDependencies';
import { IConfigUtil } from '../util/ConfigUtil';
import { LiveShareCommandBase } from './LiveShareCommandBase';
import { IStatusBarController } from '@vs/liveshare-core';
import { 
    SessionAction,
    TelemetryEventNames, 
    userAuthStateTracker,
    sessionStateTracker,
    CommandContext,
    telemetryCommandDecorator,
    auth,
    Settings
} from '@vs/liveshare-core';
export function builder(dependencies: IDependencies): DisableVSCodeAccountAuth {
    return new DisableVSCodeAccountAuth(
                dependencies.configUtil(),
                dependencies.authService(),
                dependencies.statusBarController(),
            );
}

@telemetryCommandDecorator(TelemetryEventNames.DISABLE_VSCODE_ACCOUNT_AUTH, TelemetryEventNames.DISABLE_VSCODE_ACCOUNT_AUTH_FAULT, 'DisableVSCodeAccountAuth', 1)
export class DisableVSCodeAccountAuth extends LiveShareCommandBase {

    constructor(
        private readonly configUtil: IConfigUtil,
        private readonly authService: vsls.AuthenticationService,
        private readonly statusBarController: IStatusBarController,
    ) {
        super();
    }

    public async invoke(options: any, context: ICommandContext) {
        const isVSCodeAccountAuthEnabled = this.configUtil.get(this.configUtil.KEYS.isVSCodeAccountAuthEnabled);
        // if already disabled, noop
        if (isVSCodeAccountAuthEnabled === false) {
            return;
        }

        const tokens = await auth.API.getCachedTokens();
        if (tokens.length) {
            await this.signInToLSAgent(tokens[0].accessToken);
        } else {
            // perform default sign in with agent
            await vscode.commands.executeCommand(`${this.configUtil.get<string>(this.configUtil.KEYS.commandPrefix)}.signin`, true);
        }
        await this.configUtil.save(this.configUtil.KEYS.isVSCodeAccountAuthEnabled, false);
        await vscode.commands.executeCommand('setContext', CommandContext.vscodeAccountAuthEnabled, Settings.isVSCodeAccountAuth);
        this.statusBarController.refresh();
    }

    private async signInToLSAgent(token: string) {
        // sign in with the token
        const userInfo = await this.authService.loginAsync(
                    { token: token },
                    {
                        cache: true,
                        cacheDefault: true
                    });
        userAuthStateTracker.userInfo = userInfo;
        const action = (userInfo)
            ? SessionAction.SignInSuccess 
            : SessionAction.SignInError;
        sessionStateTracker.transition(action);
    }
}
