import * as vscode from 'vscode';
import { UIDebugEvent, DebugMessageEvent, UIDebugEventTypes, DebugMessageType } from '../workspace/contract/debugEvents';
import { IRPCClient } from '../abstractions/IRPCClient';
import {
    EXTENSION_ROOT_PATH,
    DOTNET_ROOT_ENVIRONMENT_VARIABLE_NAME,
    DOTNET_ROOT_X86_ENVIRONMENT_VARIABLE_NAME } from '../constants';
import { OSPlatform } from '@vs/vso-node-utils';
import * as path from 'path';
import os = require('os');
import { fileAccess } from '@vs/vscode-command-framework';
import { 
    JoinDebugManager as JoinDebugManagerBase,
    DebugType
} from '@vs/liveshare-debug';
import {TraceSource } from '@vs/vso-logging';
import {
    vsls,
    ISessionContext,
    IFileSystemManager,
    IPathManager,
    IClientAccessCheck,
    workspaceSessionInfoTracker,
} from '@vs/liveshare-core';
import { IHostAdapterService } from './IHostAdapterService';
import { AdapterExecutableProvider } from './adapterExecutableProvider';
import { PackageManager } from '../packageManager';

export class JoinDebugManager extends JoinDebugManagerBase implements vscode.DebugAdapterDescriptorFactory {
    private static readonly debugSessionHostServiceName: string = 'DebugSessionHostService';
    private static readonly uiDebugEventName: string = 'uIDebugEvent';
    private static readonly insufficientAccessExceptionEventType = 'insufficientAccessException';

    private activeEventNotifications: Map<string, NotificationEntry[]> = new Map();
    private adapterExecutableProvider: AdapterExecutableProvider;

    constructor(
        private rpcClient: IRPCClient,
        private hostAdapterService: IHostAdapterService,
        debuggerHostService: vsls.DebuggerHostService,
        sessionContext: ISessionContext,
        fileSystemManager: IFileSystemManager,
        pathManager: IPathManager,
        clientAccessCheck: IClientAccessCheck,
        trace: TraceSource) {
            super(debuggerHostService,
                sessionContext,
                fileSystemManager,
                pathManager,
                clientAccessCheck,
                trace);
    }

    public async init(): Promise<void> {
        // register 'cascade' to intercept our launch configurations
        vscode.debug.registerDebugConfigurationProvider(DebugType.join, this);

        // advise to start/terminate vsCode debug sessions
        vscode.debug.onDidStartDebugSession(this.onDidStartDebugSessionExtension, this, this.eventRegistrations);
        vscode.debug.onDidTerminateDebugSession(this.onDidTerminateDebugSessionExtension, this, this.eventRegistrations);
        vscode.debug.onDidReceiveDebugSessionCustomEvent(this.onDidReceiveDebugSessionCustomEvent, this, this.eventRegistrations);
    
        // register adapter executable provider
        if (vscode.debug.registerDebugAdapterDescriptorFactory) {
            vscode.debug.registerDebugAdapterDescriptorFactory(DebugType.join, this);
        } else if (vscode.debug.registerDebugAdapterProvider) {
            vscode.debug.registerDebugAdapterProvider(DebugType.join, new JoinDebugAdapterProvider());
        } else {
            this.adapterExecutableProvider = new AdapterExecutableProvider(JoinDebugAdapterProvider.adapterExecutableName, this.trace);
            vscode.debug.registerDebugConfigurationProvider(DebugType.join, this.adapterExecutableProvider);
        }
        
        await super.init();
    }

    public createDebugAdapterDescriptor(session: vscode.DebugSession, executable: vscode.DebugAdapterExecutable | undefined): vscode.ProviderResult<vscode.DebugAdapterDescriptor> {
        return JoinDebugAdapterProvider.getDebugAdapterExecutable(session);
    }

    protected async setupDebugConfiguration(debugConfiguration: vscode.DebugConfiguration): Promise<void> {
        // TODO: we still need to pass a local path to the file service created by our adapter
        // but for VSCode it won't be used since we are starting to use the vsls: scheme
        let wsLocalPath = path.join(os.tmpdir(), workspaceSessionInfoTracker.workspaceSessionInfo.id);
        if (!await fileAccess.existsAsync(wsLocalPath)) {
            await fileAccess.mkdirAsync(wsLocalPath);
        }

        debugConfiguration.localPath = wsLocalPath;
        debugConfiguration.pipeName = this.hostAdapterService.pipeName;

        // Note: this wil be deprecapted once we move to the new mechanism to pass adapter arguments
        if (this.adapterExecutableProvider) {
            await this.adapterExecutableProvider.setAdapterArguments(JoinDebugAdapterProvider.getDebugAdapterArguments(debugConfiguration));
        }
    }
 
    private async onDidStartDebugSessionExtension(eventData: vscode.DebugSession): Promise<void> {
        if (eventData.type === DebugType.join) {
            this.trace.info(`Extension: Starting joined debug session:${eventData.id} name:${eventData.name}`);

            // store the shared debug session id and the vsCode debug session
            let response = await eventData.customRequest('debugSessionId');
            let sharedDebugSessionId = response.Id;

            // add notifications handlers
            const uiDebugEventName = JoinDebugManager.getDebugSessionServiceEventName(sharedDebugSessionId, JoinDebugManager.uiDebugEventName);
            const cookie = this.rpcClient.addNotificationHandler(
                uiDebugEventName,
                async (...params: any[]) => {
                    await this.onUIDebugEvent(sharedDebugSessionId, params[0].body as UIDebugEvent);
            });

            this.activeEventNotifications.set(sharedDebugSessionId, [{ eventName: uiDebugEventName, cookie: cookie}]);
        }
    }

    private onDidTerminateDebugSessionExtension(eventData: vscode.DebugSession) {
        if (eventData.type === DebugType.join) {
            this.trace.info(`Extension: Terminate joined debug session:${eventData.id}`);
            for (let [key, value] of this.activeJoinedDebugSessions) {
                if (value.id === eventData.id) {
                    // remove notification handlers
                    this.activeEventNotifications.get(key).forEach(item => {
                        this.rpcClient.removeNotificationHandler(item.eventName, item.cookie);

                    });
                    this.activeEventNotifications.delete(key);
                    break;
                }
            }
        }
    }

    private async onDidReceiveDebugSessionCustomEvent(eventData: vscode.DebugSessionCustomEvent): Promise<void> {
        if (eventData.event === JoinDebugManager.insufficientAccessExceptionEventType) {
            await vscode.window.showErrorMessage(eventData.body.Message);
        }
    }

    // Called when a UIDebugEvent is notified from a shared debug session
    private async onUIDebugEvent(sharedDebugSessionId: string, e: UIDebugEvent): Promise<void> {
        if (e.type === UIDebugEventTypes.debugMessage) {
            const debugMessageEvent = <DebugMessageEvent>e;
            if (debugMessageEvent.MessageType & DebugMessageType.MessageBox) {
                await vscode.window.showInformationMessage(
                    `The host’s debug session has been paused for the following reason: '${debugMessageEvent.Message}'`);
            }
        }
    }

    // Return the service name being published by the host for an active debug session
    private static getDebugSessionServiceEventName(debugSessionId: string, eventName: string): string {
        return JoinDebugManager.debugSessionHostServiceName + '-' + debugSessionId + '.' + eventName;
    }
}

interface NotificationEntry {
    eventName: string;
    cookie: number;
}


/**
 * This class will implement DebugConfigurationProvider for the vslsJoin type and be able to pass the --capabilities64 option
 */
class JoinDebugAdapterProvider implements vscode.DebugAdapterProvider {
    public static readonly adapterExecutableName = 'Microsoft.VisualStudio.LiveShare.Debugger.VSCodeAdapter';

    public provideDebugAdapter(
        session: vscode.DebugSession,
        executable: vscode.DebugAdapterExecutable | undefined): vscode.ProviderResult<vscode.DebugAdapterDescriptor> {

        return JoinDebugAdapterProvider.getDebugAdapterExecutable(session);
    }

    public static getDebugAdapterExecutable(session: vscode.DebugSession) {
        let adapterBinPath = path.join(
            EXTENSION_ROOT_PATH,
            'dotnet_modules',
            JoinDebugAdapterProvider.adapterExecutableName);
        if (os.platform() === OSPlatform.WINDOWS) {
            adapterBinPath += '.exe';
        }

        const dotnetInstallPath = PackageManager.getDotnetInstallPath();
        const options = {
            env: {
                [`${DOTNET_ROOT_ENVIRONMENT_VARIABLE_NAME}`]: dotnetInstallPath,
                [`${DOTNET_ROOT_X86_ENVIRONMENT_VARIABLE_NAME}`]: dotnetInstallPath
            }
        };
        
        return new vscode.DebugAdapterExecutable(adapterBinPath, JoinDebugAdapterProvider.getDebugAdapterArguments(session.configuration), options);
    }

    /**
     * Note this method expect the debug configuration already have the 'injected' debugSession
     * @param debugConfig
     */
    public static getDebugAdapterArguments(debugConfig: vscode.DebugConfiguration) {
        const adapterArguments = [];
        const capabilities = debugConfig.debugSession.capabilities;
        if (capabilities) {
            const json = JSON.stringify(capabilities);
            const encodedCapabilities = Buffer.from(json).toString('base64');
            adapterArguments.push('--capabilities64', encodedCapabilities);
        }

        return adapterArguments;
    }
}