import * as vscode from 'vscode';
import * as path from 'path';

import * as config from '../config';

import { iconsRoot } from './UserIconsProvider';
import { ViewItem } from '@vs/liveshare-api';
import { ExtensionUtil } from '../extensionUtil';

import { setTimeout } from 'timers';
import { showWelcomePage, WelcomePageSource } from '../welcomePage/welcomePageUtil';

import { getLabelAndLinkTreeViewItems } from './TreeViewUtils';

import {
    TelemetryEvent
} from '@vs/vso-telemetry';

import {
    CommandId,
    SessionState,
    SessionStateChangedEventArgs,
    sessionStateTracker,
    TelemetryEventNames, 
    ExtensionUtil as ExtensionUtilCore,
    TreeViewItem
} from '@vs/liveshare-core';

enum HelpViewletState {
    Question,
    Survey,
    ThankYou,
    Default
}

export class HelpViewletProvider implements vscode.TreeDataProvider<TreeViewItem> {

    private changeEventEmitter = new vscode.EventEmitter<TreeViewItem | undefined>();
    public readonly onDidChangeTreeData = this.changeEventEmitter.event;

    private state = HelpViewletState.Default;

    constructor() {
        sessionStateTracker.onStateChanged(this.onStateChanged);
        ExtensionUtilCore.registerCommand(CommandId.provideFeedback, this.provideFeedback, this);
        ExtensionUtilCore.registerCommand(CommandId.openLink, this.openLink);
        ExtensionUtilCore.registerCommand(CommandId.reportAProblem, this.reportAProblem);
        ExtensionUtilCore.registerCommand(CommandId.moreInfo, this.moreInfo);
        ExtensionUtilCore.registerCommand(CommandId.configureSettings, this.configureSettings);
    }

    private onStateChanged = (e: SessionStateChangedEventArgs) => {
        // Reset the feedback question on Share/Join
        if (e.newState === SessionState.Shared || e.newState === SessionState.Joined) {
            this.setState(HelpViewletState.Default);
        }

        if (e.newState === SessionState.SignedIn &&
            (e.oldState === SessionState.Shared || e.oldState === SessionState.Joined)
        ) {
            this.sessionEnd();
        }
    }

    private async sessionEnd() {
        // Request taking survey with .01 probability
        if (await this.showSurvey()) {
            this.setState(HelpViewletState.Survey);
        // Request feedback in every 5 session. When survey prompted, do not show feedback question
        } else if (!(await config.get(config.Key.dontRequestFeedback)) && (await this.getSessionNumber() % 5 === 0) ) {
            this.setState(HelpViewletState.Question);
        }
    }

    private setState(viewletState: HelpViewletState) {
        this.state = viewletState;
        this.refresh();
    }

    public refresh = () => this.changeEventEmitter.fire();

    public getTreeItem = (element: TreeViewItem) => element;

    public async getChildren(element?: TreeViewItem): Promise<TreeViewItem[]> {
        return await (element ? this.getElementChildren(element) : this.getDefaultRootChildren());
    }

    private async getElementChildren(element: TreeViewItem): Promise<TreeViewItem[]> {
       return await this.getFeedbackChildren();
    }

    private async provideFeedback(feedbackType: any) {
         const feedback = feedbackType.name;

         TelemetryEvent.create(TelemetryEventNames.FEEDBACK, {
            properties: {
                feedback
            }
        }).send();

         if (feedback ===  ViewItem.DontAskAgain) {
            await config.save(config.Key.dontRequestFeedback, true);
         }
         this.feedbackReceived();
    }

    private async feedbackReceived() {
        this.setState(HelpViewletState.ThankYou);
        setTimeout(() => {
            this.setState(HelpViewletState.Default);
        }, 5000);
    }

    private async openLink(url: string) {
        TelemetryEvent.create(TelemetryEventNames.OPEN_LINK, {
            properties: {
                url
            }
        }).send();
        ExtensionUtilCore.openBrowser(url);
    }

    private async reportAProblem() {
        ExtensionUtilCore.reportIssue();
    }

    private async moreInfo() {
        await showWelcomePage(WelcomePageSource.Help);
    }

    private async configureSettings() {
        const { name, publisher } = require('../../package.json');
        await vscode.commands.executeCommand('workbench.action.openSettings', `@ext:${publisher}.${name}`);
    }

    private async getFeedbackChildren() {

        let result: TreeViewItem[] = [];

        if (this.state === HelpViewletState.Question) {
            result = [
                new TreeViewItem({
                    type: ViewItem.GoodFeedback,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: '🙂 It was great!',
                    command: {
                        title: 'It was great!',
                        command: CommandId.provideFeedback,
                        arguments: [{ name: ViewItem.GoodFeedback }]
                    }
                }),

                new TreeViewItem({
                    type: ViewItem.BadFeedback,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: '☹️ Needs improvement',
                    command: {
                        title: 'Needs improvement',
                        command: CommandId.provideFeedback,
                        arguments: [{ name: ViewItem.BadFeedback }]
                    }
                }),

                new TreeViewItem({
                    type: ViewItem.DontAskAgain,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: '⛔️ Don\'t ask again',
                    command: {
                        title: 'Don\'t ask again',
                        command: CommandId.provideFeedback,
                        arguments: [{ name: ViewItem.DontAskAgain }]
                    }
                })
            ];
        } else if (this.state === HelpViewletState.ThankYou) {
            result = [
                new TreeViewItem({
                    type: ViewItem.Thankyou,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: 'Thank you for your feedback!'
                })
            ];
        }
        return result;
    }

    private getSessionNumber() {
        return config.get<number>(config.Key.sessionCount) + 1;
    }

    private async showSurvey(): Promise<boolean> {
        const lastShownDate = await config.get<number>(config.Key.surveyShownDate) || 0;

        const timeDiff = Date.now() - lastShownDate;
        const millisecondsInDay = 24 * 60 * 60 * 1000;

        // if user never seen the survey or If user had seen survey before but 90 days past, then calculate probability
        if (timeDiff >= 90 * millisecondsInDay) {
            return Math.random() <= .01;
        }
        return false;
    }

    private async saveSurveyShownDate(): Promise<void> {
        const surveyShownDate = Date.now();
        await config.save(config.Key.surveyShownDate, surveyShownDate);
    }

    public async showSurveyToast(): Promise<void> {
        const takeSurveyToastButton = { title: 'Take Survey' };
        const result = await vscode.window.showInformationMessage( 'We\'d love to hear about your Live Share experience! Do you mind taking a quick feedback survey?', takeSurveyToastButton);
        if (result) {
            ExtensionUtilCore.openBrowser('https://aka.ms/vsls-nps');
        } else {
            (new TelemetryEvent(TelemetryEventNames.DISMISS_SURVEY)).send();
        }
    }

    private async getDefaultRootChildren() {

        let result: TreeViewItem[] = [];

        if (this.state === HelpViewletState.Survey) {
            this.showSurveyToast();
            result.push(
                new TreeViewItem({
                    type: ViewItem.Survey,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: `Take a feedback survey`,
                    command: {
                        title: 'Take a feedback survey',
                        command: CommandId.openLink,
                        arguments: ['https://aka.ms/vsls-nps']
                    },
                    iconPath: {
                        dark: path.join(iconsRoot, '/dark/survey-dark.svg'),
                        light: path.join(iconsRoot, '/light/survey-light.svg')
                    }
                })
            );
            this.saveSurveyShownDate();
        } else if (this.state === HelpViewletState.Question || this.state === HelpViewletState.ThankYou) {
            result.push(
                new TreeViewItem({
                    type: ViewItem.SessionFeedbackQuestion,
                    collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
                    label: `How was your collaboration session?`,
                    iconPath: {
                        dark: path.join(iconsRoot, '/dark/survey-dark.svg'),
                        light: path.join(iconsRoot, '/light/survey-light.svg')
                    },
                })
            );
        }

        result.push(
            new TreeViewItem({
                type: ViewItem.TweetUsYourFeedback,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: `Tweet us your feedback`,
                command: {
                    title: 'Tweet us your feedback',
                    command: CommandId.openLink,
                    arguments: ['https://aka.ms/vsls/TwitterFeedback']
                },
                iconPath: {
                    dark: path.join(iconsRoot, '/twitter.svg'),
                    light: path.join(iconsRoot, '/twitter.svg')
                }
            })
        ),

        result.push(
            new TreeViewItem({
                type: ViewItem.ReportAProblem,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: `Report a problem`,
                command: {
                    title: 'Report a problem',
                    command: CommandId.reportAProblem
                },
                iconPath: {
                    dark: path.join(iconsRoot, '/dark/github-dark.svg'),
                    light: path.join(iconsRoot, '/light/github-light.svg')
                }
            })
        );

        result.push(
            new TreeViewItem({
                type: ViewItem.ConfigureSettings,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: `Configure Settings`,
                command: {
                    title: 'Configure Settings',
                    command: CommandId.configureSettings
                },
                iconPath: {
                    dark: path.join(iconsRoot, '/dark/settings.svg'),
                    light: path.join(iconsRoot, '/light/settings.svg')
                }
            })
        );

        result.push(
            new TreeViewItem({
                type: ViewItem.MoreInfo,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: `More Info`,
                command: {
                    title: 'More Info',
                    command: CommandId.moreInfo,

                },
                iconPath: {
                    dark: path.join(iconsRoot, '/dark/info-dark.svg'),
                    light: path.join(iconsRoot, '/light/info-light.svg')
                }
            })
        );

        const sessionExplorerLinksAndLabels = await getLabelAndLinkTreeViewItems('HelpViewlet');
        result.push(...sessionExplorerLinksAndLabels);

        return result;
    }
}