import { vsls } from '@vs/liveshare-core';
import * as config from '../../config';
import * as vscode from 'vscode';
import * as fs from 'fs-extra';

import { IDependencies } from '../IDependencies';
import { Lazy, ICoEditingManager } from '../abstractions/Interfaces';

import {
    IClientAccessCheck,
    IPathManager,
    IFileSystemManager,
    ISessionContext,
    userAuthStateTracker,
} from '@vs/liveshare-core';

class CoEditingManagerBase implements ICoEditingManager {
    private readonly sessionContext: ISessionContext;
    private readonly sourceEventService: vsls.SourceEventService;
    private readonly fileSystemManager: Lazy<IFileSystemManager>;
    private readonly clientAccessCheck: Lazy<IClientAccessCheck>;
    protected readonly pathManager: IPathManager;
    protected readonly fileService: vsls.FileService;
    private readonly syncService: vsls.SyncService;

    constructor (dependencies: IDependencies) {
        this.sessionContext = dependencies.sessionContext();
        this.sourceEventService = dependencies.sourceEventService();
        this.fileService = dependencies.fileService();
        this.pathManager = dependencies.pathManager();
        this.clientAccessCheck = dependencies.clientAccessCheck;
        this.fileSystemManager = dependencies.fileSystemManager;
        this.syncService = dependencies.syncService();
    }

    public async init(isGuest: boolean = false): Promise<void> {
        this.sessionContext.initCoEditingContext({
            joinCompleted: Promise.resolve(),
            sourceEventService: this.sourceEventService,
            userInfo: userAuthStateTracker.userInfo,
            fileSystemService: this.fileService,
            pathManager: this.pathManager,
            clientAccessCheck: this.clientAccessCheck,
            isGuest,
            fileSystemManager: this.fileSystemManager,
            syncService: this.syncService,
        });
    }

    public async dispose(): Promise<void> {}
}

export class CoEditingHostManager extends CoEditingManagerBase {
    public async init(): Promise<void> {
        if (config.get(config.Key.shareExternalFiles)) {
            let active = vscode.window.activeTextEditor;
            if (active) {
                const isInWorkspace = !!(vscode.workspace.getWorkspaceFolder(active.document.uri));
                const isFileExists = (fs.existsSync(active.document.uri.fsPath));

                if (!isInWorkspace && isFileExists) {
                    await this.fileService.registerExternalFilesAsync([active.document.fileName]);
                }
            }
        }
        super.init(false);
    }
}

export class CoEditingGuestManager extends CoEditingManagerBase {
    public async init(): Promise<void> {
        super.init(true);
    }
}
