'use strict';

import { Disposable, Inittable } from '@vs/vscode-command-framework';

import { WorkspaceTaskService } from '../../tasks/workspaceTaskService';
import { Lazy, IWorkspaceTaskManager } from '../abstractions/Interfaces';
import { IDependencies } from '../IDependencies';

export default class WorkspaceTaskManager extends Inittable(Disposable(Object)) implements IWorkspaceTaskManager {
    private workspaceTaskService: WorkspaceTaskService | undefined;

    constructor(private readonly context: IDependencies) {
        super();
    }

    public async init(): Promise<void> {
        await super.init();

        this.workspaceTaskService = new WorkspaceTaskService(this.context);
        await this.workspaceTaskService.init();
    }

    public async dispose(): Promise<void> {
        if (this.workspaceTaskService) {
            await this.workspaceTaskService.dispose();
            this.workspaceTaskService = undefined;
        }

        await super.dispose();
    }
}