import * as vscode from 'vscode';

import { ICommandContext } from '@vs/vscode-command-framework';

import { vsls } from '@vs/liveshare-core';

import { IDependencies } from '../IDependencies';
import { IConfigUtil } from '../util/ConfigUtil';
import { LiveShareCommandBase } from './LiveShareCommandBase';

import { 
    CommandContext,
    TelemetryEventNames,
    telemetryCommandDecorator,
    liveshareGithubStrategy,
    IStatusBarController,
    Settings
} from '@vs/liveshare-core';

export function builder(dependencies: IDependencies): EnableVSCodeAccountAuth {
    return new EnableVSCodeAccountAuth(
        dependencies.configUtil(),
        dependencies.authService(),
        dependencies.statusBarController()
    );
}

@telemetryCommandDecorator(TelemetryEventNames.ENABLE_VSCODE_ACCOUNT_AUTH, TelemetryEventNames.ENABLE_VSCODE_ACCOUNT_AUTH_FAULT, 'EnableVSCodeAccountAuth', 1)
export class EnableVSCodeAccountAuth extends LiveShareCommandBase {

    constructor(
        private readonly configUtil: IConfigUtil,
        private readonly authService: vsls.AuthenticationService,
        private readonly statusBarController: IStatusBarController,
    ) {
        super();
    }

    public async invoke(options: any, context: ICommandContext) {
        const isVSCodeAccountAuthEnabled = this.configUtil.get(this.configUtil.KEYS.isVSCodeAccountAuthEnabled);
        // if already enabled, noop
        if (isVSCodeAccountAuthEnabled) {
            return;
        }

        try {
            const authToken = await this.authService.getCachedTokenAsync();
            if (authToken && authToken.token) {
                const strategy = liveshareGithubStrategy;

                const vscodeAccountToken = strategy.parseTokenPayloadFromAccessToken(authToken.token);
                strategy.signalNewToken(vscodeAccountToken);
            }

            await this.configUtil.save(this.configUtil.KEYS.isVSCodeAccountAuthEnabled, true);
            await vscode.commands.executeCommand('setContext', CommandContext.vscodeAccountAuthEnabled, Settings.isVSCodeAccountAuth);
            this.statusBarController.refresh();
        } catch (e) {
            /* old agents can throw since they dont have the `getCachedToken` method yet, ignore */
        }
    }
}
