import { CancellationToken } from 'vscode';

import { vsls } from '@vs/liveshare-core';

import { IAuthenticationFindCodeUtil } from '../abstractions/IAuthenticationFindCodeUtil';

export class AuthenticationFindCodeUtilMacWin implements IAuthenticationFindCodeUtil {
    constructor(
        private authService: vsls.AuthenticationService) {
    }

    public async findLoginCode(instanceId: string, cancellationToken?: CancellationToken): Promise<string> {
        return await this.authService.findLoginCodeAsync(instanceId, cancellationToken);
    }
}