import { fileAccess } from '@vs/vscode-command-framework';
import * as path from 'path';

import { SharedColors } from '@vs/liveshare-core';
import { traceSource } from '@vs/vscode-command-framework';
import { renderCircleIcon } from './renderUserCircleIcon';
import { EXTENSION_ROOT_PATH } from '../constants';

export const iconsRoot = path.join(EXTENSION_ROOT_PATH, './images/');

interface ISessionExplorerIcon {
    normal: string;
    filled: string;
}

class IconsProvider {

    private trace = traceSource.withName('IconsProvider');   

    private icons: { [key: string]: ISessionExplorerIcon; } = {};

    public async getIcon(color: string): Promise<ISessionExplorerIcon | null> {
        const currentIcon = this.icons[color];

        if (currentIcon) {
            return currentIcon;
        }

        try {
            this.icons[color] = await this.createIconBundle(color);
        } catch (e) {
            this.trace.error('Creating icon bundle failed', e);
            return null;
        }

        return this.icons[color];
    }

    public async getIconByUserId(userId: number) {
        const color = SharedColors.requestColor(userId);
        const { backgroundColor, textColor } = color;
        const red = parseInt(`${255 * backgroundColor.red}`, 10);
        const green = parseInt(`${255 * backgroundColor.green}`, 10);
        const blue = parseInt(`${255 * backgroundColor.blue}`, 10);
        const colorString = `rgb(${red}, ${green}, ${blue})`;

        return await this.getIcon(colorString);
    }

    private createIconBundle = async (color: string): Promise<ISessionExplorerIcon> => {
        const cleanColorName = color.replace(/\,|\.|\(|\)|\s/gim, '_');


        const normalPath = path.join(iconsRoot, `./user-icon-${cleanColorName}-icon.svg`);
        const filledPath = path.join(iconsRoot, `./user-icon-${cleanColorName}-filled-icon.svg`);

        if ((await fileAccess.existsAsync(normalPath)) && (await fileAccess.existsAsync(filledPath))) {
            return {
                normal: normalPath,
                filled: filledPath
            };
        }

        await fileAccess.writeFileAsync(normalPath, renderCircleIcon(color, false));
        await fileAccess.writeFileAsync(filledPath, renderCircleIcon(color, true));

        return {
            normal: normalPath,
            filled: filledPath
        };
    }
}

export const userIconProvider = new IconsProvider();
