import { Telemetry, TelemetryEvent, FaultType } from '@vs/vso-telemetry';
import { TelemetryEventNames, TelemetryPropertyNames }  from '@vs/liveshare-core';

export class RemoteServiceTelemetry {
    public static readonly FEATURE_PREFIX = 'RemoteService/';
    public static readonly PROPERTY_PREFIX = TelemetryPropertyNames.FEATURE_NAME + 'RemoteService.';

    public static sendRequestSummary(serviceName: string, methodName: string, responseTimes: number[]): void {
        let summaryEvent = new TelemetryEvent(EventNames.SERVICE_REQUEST);
        summaryEvent.addProperty(PropertyNames.SERVICE_NAME, serviceName);
        summaryEvent.addProperty(PropertyNames.METHOD_NAME, methodName);
        summaryEvent.addMeasure(PropertyNames.TOTAL_COUNT, responseTimes.length);
        summaryEvent.addMeasure(PropertyNames.MAX_TIME, Math.max(...responseTimes));
        summaryEvent.addMeasure(PropertyNames.MIN_TIME, Math.min(...responseTimes));
        summaryEvent.addMeasure(PropertyNames.AVERAGE_TIME, responseTimes.reduce((p, c) => p + c, 0) / responseTimes.length);
        summaryEvent.send();
    }

    public static sendServiceFault(serviceName: string, methodName: string, error: Error): void {
        Telemetry.sendFault(
            EventNames.HANDLE_REQUEST_ERROR,
            FaultType.Error,
            `Error processing a service request '${serviceName}.${methodName}'. ${error.message}`,
            error);
    }

    public static sendClientFault(serviceName: string, methodName: string, error: Error): void {
        Telemetry.sendFault(
            EventNames.SEND_REQUEST_ERROR,
            FaultType.Error,
            `Error sending a remote service request '${serviceName}.${methodName}'. ${error.message}`,
            error);
    }
}

class EventNames {
    public static readonly SERVICE_REQUEST = 'service-request';
    public static readonly HANDLE_REQUEST_ERROR = TelemetryEventNames.FAULT_PREFIX + 'handle-request-error';
    public static readonly SEND_REQUEST_ERROR = TelemetryEventNames.FAULT_PREFIX + 'send-request-error';
}

class PropertyNames {
    public static readonly SERVICE_NAME = TelemetryPropertyNames.FEATURE_NAME + 'ServiceName';
    public static readonly METHOD_NAME = TelemetryPropertyNames.FEATURE_NAME + 'MethodName';
    public static readonly TOTAL_COUNT = TelemetryPropertyNames.FEATURE_NAME + 'TotalCount';
    public static readonly MAX_TIME = TelemetryPropertyNames.FEATURE_NAME + 'MaxTime';
    public static readonly MIN_TIME = TelemetryPropertyNames.FEATURE_NAME + 'MinTime';
    public static readonly AVERAGE_TIME = TelemetryPropertyNames.FEATURE_NAME + 'AverageTime';
}
