import * as url from 'url';
import * as net from 'net';

import * as rpc from 'vscode-jsonrpc';
import { traceSource } from '@vs/vscode-command-framework';

import { Telemetry, TelemetryResult } from '@vs/vso-telemetry';

import {
    TelemetryEventNames,
    TelemetryPropertyNames,
    vsls
} from '@vs/liveshare-core';
import { getPipePath } from '@vs/vso-node-utils';
import { RpcClient as RPCClientBase } from '@vs/vso-rpc';
import { IRPCClient } from '../IRPCClient';

export class RPCClient extends RPCClientBase implements IRPCClient {
    public hostSessionId: number;
    public agentProcessId: number;

    private socket: net.Socket;
    private uri: url.Url;
    private initPromise: Promise<void>;

    private readonly maxRetryCount = 9;
    
    public constructor(private uriPromise?: (retryCount: number) => Promise<url.Url>) {
        super({
            create: (rpcClient) => Promise.resolve(this.connection)
        }, traceSource.withName(vsls.TraceSources.ClientRpc));
    }

    public get isDisposed(): boolean {
        return this.disposed;
    }

    public connectionOwner: string;

    protected onRpcSessionConnected(): Promise<void> {
        return Promise.resolve();
    }

    public async init(retryCount = 0, retryInterval: number = null): Promise<void> {
        const currentRetryInterval = retryInterval ||
            (retryCount === this.maxRetryCount ? 50 : (retryCount === 0 ? 0 : 100));

        this.logger.verbose(`RPCClient.init retryCount:${retryCount} currentRetryInterval:${currentRetryInterval}`);
        this.uri = await this.uriPromise(retryCount);
       
        await new Promise((resolve, reject) => {
            let startEvent = Telemetry.startTimedEvent(TelemetryEventNames.START_AGENT_CONNECTION);
            startEvent.addProperty(TelemetryPropertyNames.AGENT_START_CONNECTION_RETRY_COUNT, (this.maxRetryCount - retryCount).toString());
            startEvent.addProperty(TelemetryPropertyNames.AGENT_START_CONNECTION_URI_PROTOCOL, this.uri.protocol);
            startEvent.addProperty(TelemetryPropertyNames.AGENT_START_CONNECTION_OWNER, this.connectionOwner || 'client');

            let didSucceed = false;

            if (this.uri.protocol === 'net.tcp:' &&
                this.uri.hostname === 'localhost' &&
                this.uri.port) {
                const port: number = parseInt(this.uri.port, 10);
                this.socket = net.createConnection({ port: port });
            } else if (this.uri.protocol === 'net.pipe:' && this.uri.hostname === 'localhost') {
                const pipe: string = this.uri.pathname.substr(1);
                this.socket = net.createConnection(getPipePath(pipe));
            } else {
                reject(new Error('Invalid agent URI: ' + url.format(this.uri)));
                return;
            }

            const messageReader = this.createFilteredMessageReader(new rpc.StreamMessageReader(this.socket));
            const messageWriter = this.createFilteredMessageWriter(new rpc.StreamMessageWriter(this.socket));            
            this.setConnection(rpc.createMessageConnection(messageReader, messageWriter, {
                error: (message) => this.logger.error(message),
                warn: (message) => this.logger.warning(message),
                info: (message) => this.logger.info(message),
                log: (message) => this.logger.verbose(message),
            }));

            this.socket.on('connect', () => {
                didSucceed = true;
                this.logger.info('Agent connection success - ' + url.format(this.uri));
                startEvent.end(TelemetryResult.Success, 'Agent connection success.');
                this.onRpcSessionConnected().then(() => resolve());
            });

            this.connection.onError((error: [Error, rpc.Message, number]) => {
                const e = error[0];

                if (retryCount < this.maxRetryCount) {
                    this.connection.dispose();
                    this.socket.destroy();
                    this.logger.verbose('Agent connection not completed: ' + e + '; Retrying...');

                    // Recursive call
                    setTimeout(() => {
                        this.init(++retryCount, retryInterval)
                            .then(() => resolve())
                            .catch(reject);
                    }, currentRetryInterval);
                } else {
                    if (!didSucceed) {
                        startEvent.end(TelemetryResult.Failure, 'Agent connection failed. ' + e);
                    }

                    // No more retries. Dispose with the error from the last connection attempt.
                    this.dispose(e);
                    this.logger.error('Agent connection failed: ' + e);
                    reject(e);
                }
            });
            this.connection.listen();
        });
    }

    protected async ensureConnectionInternal(): Promise<void> {
        if (!!this.initPromise) {
            // some other async caller is already connecting
            await this.initPromise;
        }

        if (!this.connection) {
            // the caller is connecting
            this.initPromise = this.init();
            await this.initPromise;
        }
    }

    public dispose = (e?: Error) => {
        if (!this.disposed) {
            if (this.connection) {
                this.connection.dispose();
                this.setConnection(null);
            }

            if (this.socket) {
                this.socket.destroy();
                this.socket = null;
            }

            this.disposed = true;

            if (e) {
                this.initPromise = Promise.reject(e);
            } else {
                // The instance was disposed during extension deactivation.
                // Create an init promise that never resolves, to block any
                // further communication attempts during extension deactivation.
                this.initPromise = new Promise((resolve) => {});
            }
        }
    }
}
