import { PolicyResolutionStrategy } from './policyResolutionStrategy';

export class AllowedDomainsStrategy implements PolicyResolutionStrategy<string[]> {
    public readonly default: string[] = [];

    public resolvePolicy(policyValues: string[][]): string[] {
        if (!policyValues || policyValues.length === 0)
            return this.default;

        let result = new Array<string>();
        policyValues.forEach(listOfDomains => {
            result = result.concat(listOfDomains);
        });

        return result;
    }
}
