import { vsls } from '@vs/liveshare-core';
import { Signal } from '@vs/vso-rpc';
import { IRpcConnectionOpenner } from '../IRpcConnectionOpenner';

class RpcConnectionOpenner implements IRpcConnectionOpenner {
    public connectionSignal = new Signal();

    public async openConnection(workspaceInfo: vsls.WorkspaceJoinInfo): Promise<vsls.WorkspaceJoinInfo> {
        return workspaceInfo;
    }
}

export const rpcConnectionOpenner = new RpcConnectionOpenner();
    