export function builder(deps: IDependencies): JoinReloadCommand {
    return new JoinReloadCommand(
        deps.sessionContext(),
        deps.workspaceService(),
        deps.coEditingGuestManager(),
        deps.coEditingCommands(),
        deps.accessControlManager(),
        deps.searchProviderManager(),
        deps.additionalRootsManager(),
        deps.joinDebugManager(),
        deps.joinBreakpointManager(),
        deps.workspaceTaskClientManager(),
        deps.fileSystemManager(),
        deps.guestSourceControlManager(),
        deps.configUtil(),
        resetAuthReloadFlag,
        deps.commentManager(),
        deps.guestChannelService(),
        deps.guestNotebooksService(),
    );
}

export interface ICommandOptions {
    isAllowAnonymous?: boolean;
}

export interface IJoinPostreloadCommandOptions extends ICommandOptions {
    workspaceId: string;
    isRefreshFileSystemManager: boolean;
}

const closeFolder = () => {
    dependencies.sessionContext().notJoining();
    vscode.commands.executeCommand('workbench.action.closeFolder');
};

const askToSignIn = async (message: string) => {
    const notificationUtil = dependencies.notificationUtil();
    const signInItem = { title: 'Sign in' };

    const questionResult = await notificationUtil.showErrorInformationMessage(message, { modal: true }, signInItem);

    // if user picked the `sign in` button
    if (questionResult && (questionResult.title === signInItem.title)) {
        const settings = vscode.workspace.getConfiguration();
        const workspaceId: string = settings.get(CommandId.joinWorkspaceIdSettingName);

        const joinCommandOptions: IJoinPostreloadCommandOptions = {
            workspaceId,
            isAllowAnonymous: false,
            isRefreshFileSystemManager: true
        };

        await vscode.commands.executeCommand(`${config.get<string>(config.Key.commandPrefix)}.join.postReload`, joinCommandOptions);
    } else {
        closeFolder();
    }
};

const onError = async (error: any, context: ICommandContext, options: any) => {
    switch (error.code) {
        // if failed after user was rejected due to being anonymous, we ask them to sign in
        case vsls.ErrorCodes.ForbiddenHttpStatusCode: {
            await askToSignIn(`${context.commandName}: The host doesn’t allow anonymous guests. Sign in to proceed.`);
            break;
        }
        // if failed after user was blocked due to being anonymous, we ask them to sign in
        case vsls.ErrorCodes.CollaborationSessionGuestBlocked:
        case vsls.ErrorCodes.CollaborationSessionGuestRejected: {
            if (userAuthStateTracker.isCurrentUserAnonymous()) {
                await askToSignIn(`${context.commandName}: The host rejected your anonymous request. Sign in to proceed.`);
            } else {
                closeFolder();
            }
            break;
        }
        default: {
            closeFolder();
        }
    }
};

const onErrorTelemetry = (e: any, context: ICommandContext) => {
    const { telemetryEvent } = context;

    if (telemetryEvent) {
        switch (e.code) {
            case vsls.ErrorCodes.CollaborationSessionGuestRejected: {
                telemetryEvent.addProperty(TelemetryPropertyNames.REJECTED_BY_HOST, true);
                break;
            }
            case vsls.ErrorCodes.ForbiddenHttpStatusCode: {
                telemetryEvent.addProperty(TelemetryPropertyNames.REJECTED_BY_HOST_AS_ANONYMOUS, true);
                break;
            }
            case vsls.ErrorCodes.CollaborationSessionGuestCanceled: {
                telemetryEvent.addProperty(TelemetryPropertyNames.GUEST_CANCELED, true);
                break;
            }
            case vsls.ErrorCodes.CollaborationSessionRequestTimedOut: {
                telemetryEvent.addProperty(TelemetryPropertyNames.JOIN_REQUEST_TIMED_OUT, true);
                break;
            }
            case vsls.ErrorCodes.CollaborationSessionNotFound: {
                telemetryEvent.addProperty(TelemetryPropertyNames.WORKSPACE_NOT_FOUND, true);
                break;
            }
            default: {}
        }
    }
};

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.AttemptJoining,
    authAttemptMax: 2
};

const getInviteLinkJoining = (options: IJoinPostreloadCommandOptions): InviteLinkJoining => {
    const inviteLinkJoining = MementoConfig.get<InviteLinkJoining>(options.workspaceId);
    if (inviteLinkJoining) {
        // remove from the memento
        MementoConfig.save(options.workspaceId, null);
    }

    return inviteLinkJoining;
};

/**
 * Join reload `command` that triggers when we know what workspace we
 * are connecting to (typically happens from a bank/empty workspace or
 * a newly opened copy of VS Code).
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Joining collaboration session', TelemetryEventNames.JOIN_FAULT, true, onError)
@telemetryCommandDecorator(TelemetryEventNames.JOIN_WORKSPACE, TelemetryEventNames.JOIN_FAULT, 'Join', 1, onErrorTelemetry)
@firstRunTrackingCommandDecorator(ConfigKey.commandFirstRunTrackingJoinReload)
@telemetryStatusCommandDecorator()
@validationCommandDecorator()
@sessionStateTransitionsCommandDecorator(SessionAction.AttemptJoining, SessionAction.JoiningSuccess, SessionAction.JoiningError)
@progressCommandDecorator()
@infoPageCommandDecorator(WelcomePageSource.FirstJoin)
@authenticationCommandDecorator(authOptions)
@gaNotificationCommandDecorator()
export class JoinReloadCommand extends LiveShareCommandBase implements ICancelableCommand {
    constructor(
        private readonly sessionContext: ISessionContext,
        private readonly workspaceService: vsls.WorkspaceService,
        coEditingGuestManager: ICoEditingManager,
        coeditingCommands: IInittableDisposable,
        private readonly accessControlManager: IAccessControlManager,
        searchProviderManager: ISearchProviderManager,
        additionalRootsManager: IAdditionalRootsManager,
        joinDebugManager: JoinDebugManager,
        joinBreakpointManager: IJoinBreakpointManager,
        workspaceTaskClientManager: IWorkspaceTaskClientManager,
        private fileSystemManager: IFileSystemManager,
        guestSourceControlManager: IGuestSourceControlManager,
        private configUtil: IConfigUtil,
        private resetAuthReloadFlagFunction: (mode: SignInReloadMode) => Promise<void>,
        commentManager: ICommentManager,
        guestChannelService: IGuestChannelService & IInittableDisposable,
        private readonly guestNotebooksService: IGuestNotebooksService,
    ) {
        super();

        this.postSetupManagers.push(
            { status: TelemetryPropertyNames.ADD_ADDITIONALROOTS_COMPLETE, instance: additionalRootsManager },
            { status: TelemetryPropertyNames.INIT_COEDITING_COMPLETE, instance: coEditingGuestManager },
            { status: TelemetryPropertyNames.INIT_COMMAND_COMPLETE, instance: coeditingCommands },
            { status: TelemetryPropertyNames.INIT_SEARCHPROVIDER_COMPLETE, instance: searchProviderManager },
            { status: TelemetryPropertyNames.INIT_DEBUGGING_COMPLETE, instance: joinDebugManager },
            { status: TelemetryPropertyNames.INIT_BREAKPOINT_COMPLETE, instance: joinBreakpointManager },
            { status: TelemetryPropertyNames.INIT_SOURCE_CONTROL_SERVICE_COMPLETE, instance: guestSourceControlManager },
            { status: TelemetryPropertyNames.INIT_COMMENT_SERVICE_COMPLETE, instance: commentManager },
            { status: TelemetryPropertyNames.INIT_GUEST_CHANNEL_SERVICE_COMPLETE, instance: guestChannelService },
            { status: TelemetryPropertyNames.RELOAD_END_TIME, instance: workspaceTaskClientManager },
        );
    }

    public async onCancellationRequested(options: any, context: ICommandContext): Promise<void> {
        await JoinCommandUtilities.finishInviteLinkJoining(getInviteLinkJoining(options));
    }

    public async invoke(options: IJoinPostreloadCommandOptions, context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource, telemetryEvent } = context;

        let workspaceSessionInfo: vsls.WorkspaceSessionInfo;
        let inviteLinkJoining: InviteLinkJoining;
        try {
            // If 'inviteLinkJoining' memento is found we recognize that the original join was made as an invite workflow
            inviteLinkJoining = getInviteLinkJoining(options);

            this.addInitialTelemetryProperties(telemetryEvent);
            await this.resetConfigProperties();

            let workspaceInfo = this.createWorkspaceInfo(options);
            // since the RPC connection in the web worker case will be openned at the time of invoking this command,
            // we need the place to connect to the relay. The NodeJS implementation will no-op though.
            // the `web worker` implementation will modify connection mode to always be `Local`, that's why we pipe the `workspaceInfo` thru.
            workspaceInfo = await rpcConnectionOpenner.openConnection(workspaceInfo);

            workspaceSessionInfo = await this.workspaceService.joinWorkspaceAsync(
                workspaceInfo,
                cancellationTokenSource && cancellationTokenSource.token
            );

            // it is important to set the `workspaceSessionInfo` to the `sessionContext` before we call the `postSetupMangers` as they rely on it
            workspaceSessionInfoTracker.workspaceSessionInfo = workspaceSessionInfo;

            this.addWorkspaceSessionInfoTelemetryProperties(telemetryEvent, workspaceSessionInfo);

            // Init access control manager before others because this can re-register file system provider if the session is read-only.
            // Other managers, like co-editing may try open files, and if this happens in parallel with file system provider re-registration,
            // these files may fail to load.
            await this.accessControlManager.init();
            // Init notebooks service before others because others may try to open a notebook document, which will fail
            // if the mirrored notebook content providers haven't been setup yet.
            if (getExpService()?.getTreatmentVariable(TreatmentVariables.VSCodeConfig, TreatmentVariables.NotebooksEnabled)) {
                await this.guestNotebooksService.init();
            }
            await this.invokePostSetupManagers();

            // Set joined signal after all post setup manages have completed to ensure that
            // WorkspaceProvider stat() methods resume when read-only status is already set and,
            // depending on it, WorspaceProvider is disposed so stat() can return
            // appropriate data which would make VSCode to not try to read the files of disposed
            // file system provider.
            // This is to work around VSCode bug https://github.com/Microsoft/vscode/issues/61182
            this.sessionContext.joined();

            // Apply guest settings to workspace after joined has been signaled to avoid a blocking
            // call to WorkspaceProvider's readDirectory
            await JoinCommandUtilitiesCore.applyGuestSettingsToWorkspace();

            // Set JOIN_WORKSPACE_COMPLETE telemetry point when all managers are done.
            sessionStateTracker.point(TelemetryPropertyNames.JOIN_WORKSPACE_COMPLETE);

            if (userAuthStateTracker.isCurrentUserAnonymous()) {
                // if successfuly joined as anonymous, reset the anonymous authentication reload flag
                this.resetAuthReloadFlagFunction(SignInReloadMode.Anonymous);
            } else if (userAuthStateTracker.isCustomAccount) {
                this.resetAuthReloadFlagFunction(SignInReloadMode.CustomAccount);
            }

            return true;
        } catch (e) {
            // supress the guest rejected due to being anonymous notification as we want ask
            // them to sign in without the additional message which will be triggered by this error
            // (see `onError` handler of the `errorNotificationCommandDecorator`)
            const isRejectedAnonymous = (e.code === vsls.ErrorCodes.ForbiddenHttpStatusCode);
            const isRejectedAndAnonymous = (e.code === vsls.ErrorCodes.CollaborationSessionGuestRejected);
            const isBlockedAnonymous = (e.code === vsls.ErrorCodes.CollaborationSessionGuestBlocked);

            const isOneOf = (isRejectedAnonymous || isBlockedAnonymous || isRejectedAndAnonymous);

            if (isOneOf && userAuthStateTracker.isCurrentUserAnonymous()) {
                e.isSuppressUserNotification = true;
            } else {
                this.sessionContext.notJoining();
            }

            if (e.code === vsls.ErrorCodes.CollaborationSessionGuestRejected) {
                throw new ByDesignError(ExtensionUtil.getErrorString(vsls.ErrorCodes.CollaborationSessionGuestRejected), e.code);
            } else if ( e.code === vsls.ErrorCodes.CollaborationSessionGuestBlocked) {
                throw new ByDesignError(ExtensionUtil.getErrorString(vsls.ErrorCodes.CollaborationSessionGuestBlocked), e.code);
            } else if ( e.code === vsls.ErrorCodes.CollaborationSessionUsersLimitReached) {
                throw new ByDesignError(ExtensionUtil.getErrorString(vsls.ErrorCodes.CollaborationSessionUsersLimitReached), e.code);
            } else {
                throw e;
            }
        }
        finally {
            await JoinCommandUtilities.finishInviteLinkJoining(inviteLinkJoining);
        }
    }

    private addWorkspaceSessionInfoTelemetryProperties(telemetryEvent: ITelemetryEvent, workspaceSessionInfo: vsls.WorkspaceSessionInfo) {
        telemetryEvent.addProperty(TelemetryPropertyNames.CREATED_AT, workspaceSessionInfo.createdAt);
        telemetryEvent.addProperty(TelemetryPropertyNames.UPDATED_AT, workspaceSessionInfo.updatedAt);
        telemetryEvent.addProperty(TelemetryPropertyNames.EXPIRES_AT, workspaceSessionInfo.expiresAt);
        telemetryEvent.addProperty(TelemetryPropertyNames.CONNECTION_MODE_USED, workspaceSessionInfo.connectionMode);
    }

    private createWorkspaceInfo(options: IJoinPostreloadCommandOptions): vsls.WorkspaceJoinInfo {
        return {
            id: options.workspaceId,
            connectionMode: config.get<vsls.ConnectionMode>(config.Key.connectionMode),
            clientCapabilities: config.getClientCapabilties(),
            anonymousUserName: this.configUtil.get(ConfigKey.anonymousUserName)
        };
    }

    private addInitialTelemetryProperties(telemetryEvent: ITelemetryEvent) {
        Telemetry.setCorrelationEvent(telemetryEvent);
        const correlationId = config.get<string>(config.Key.joinEventCorrelationId);
        if (correlationId) {
            telemetryEvent.addProperty(TelemetryPropertyNames.JOIN_FROM_BROWSER, 'False');
            telemetryEvent.correlateWithId(correlationId);
            telemetryEvent.addMeasure(TelemetryPropertyNames.RELOAD_START_TIME, config.get<number>(config.Key.workspaceReloadTime));
            telemetryEvent.addMeasure(TelemetryPropertyNames.RELOAD_RESUMED_TIME, (new Date()).getTime());
        } else {
            telemetryEvent.addProperty(TelemetryPropertyNames.JOIN_FROM_BROWSER, 'True');
        }
    }

    /**
     * Function to clear the config properties stashed before reload.
     */
    private async resetConfigProperties() {
        // Clear things stashed before during reload
        await config.save(config.Key.joinWorkspaceLocalPath, undefined, true, true);
        await config.save(config.Key.joinEventCorrelationId, undefined, true, true);
        await config.save(config.Key.workspaceReloadTime, undefined, true);
    }

    public async validate(options: any, context: ICommandContext) {
        // check if workspace file is broken - no vsls root folder is present, - add one!
        const isFoldersPresent = !!vscode.workspace.workspaceFolders.length;
        if (!isFoldersPresent || (vscode.workspace.workspaceFolders[0].uri.scheme !== config.get<string>(config.Key.scheme))) {
            vscode.workspace.updateWorkspaceFolders(0, null, {
                uri: vscode.Uri.parse(`${config.get<string>(config.Key.scheme)}:/`),
                name: 'Loading file tree...'
            });

            context.telemetryEvent.addProperty(TelemetryPropertyNames.RECOVER_ROOT_FOLDER, true);

            await vscode.commands.executeCommand('workbench.action.reloadWindow');
            return;
        }
    }
}
