import { ICommandContext } from '@vs/vscode-command-framework';
import { IWorkspaceEnvironmentUtil } from '../util/IWorkspaceEnvironmentUtil';

import { dependencies } from '../Dependencies';
import { showWelcomePage, WelcomePageSource } from '../../welcomePage/welcomePageUtil';
import {
    ISessionContext,
    ICommand,
    ICommandDecorator,
    DecoratorHelper
} from '@vs/liveshare-core';

export function infoPageCommandDecorator(
    welcomePageSource: WelcomePageSource) {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new InfoPageCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command,
            dependencies.sessionContext(),
            dependencies.workspaceEnvironmentUtil(),
            welcomePageSource));
}

/**
 * Validation `decorator` that executes validation func prior to running
 * core command.
 */
export class InfoPageCommandDecorator implements ICommandDecorator {
    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private sessionContext: ISessionContext,
        private workspaceEnvironmentUtil: IWorkspaceEnvironmentUtil,
        private welcomePageSource: WelcomePageSource) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;

        // Determine if we should show welcome page and open if needed
        if (this.workspaceEnvironmentUtil.isWebviewSupported()
            && !context.hasRunPreviously) {
            showWelcomePage(this.welcomePageSource);
        }
    
        result = await this.next.invoke(options, context);

        return result;
    }
}