import { Lazy, ILspServerManager } from '../abstractions/Interfaces';
import { 
    lspServer,
    UniversalLanguageServerProvider } from '@vs/liveshare-lsp';

import {
    vsls,
    IPathManager,
    IClientAccessCheck,
    ISessionContext,
} from '@vs/liveshare-core';

export class LspServerManager implements ILspServerManager {
    constructor (
        private workspaceService: vsls.WorkspaceService,
        private pathManager: IPathManager,
        private clientAccessCheck: Lazy<IClientAccessCheck>,
        private sessionContext: ISessionContext) {
    }

    public init(): Promise<void> {
        return lspServer.activateAsync(
                this.workspaceService,
                this.pathManager,
                this.clientAccessCheck,
                this.sessionContext
            );
    }

    public dispose(): Promise<void> {
        return lspServer.dispose();
    }

    public setupHandlers(languageServerProvider: UniversalLanguageServerProvider): void {
        lspServer.setupHandlers(languageServerProvider, this.pathManager, this.clientAccessCheck);
    }
}