import { LiveShareCommandBase } from './LiveShareCommandBase';
import { vsls, TelemetryPropertyNames, telemetryCommandDecorator, TelemetryEventNames } from '@vs/liveshare-core';
import { IDependencies } from '../IDependencies';
import { ICommandContext } from '@vs/vscode-command-framework';

export function builder(dependencies: IDependencies): CreateInvitationLinkCommand {
    return new CreateInvitationLinkCommand(
        dependencies.workspaceService()
    );
}

/**
 * Command that creates a new join link for the workspace based on the link options
 */
@telemetryCommandDecorator(TelemetryEventNames.CREATE_INVITATION_LINK, TelemetryEventNames.CREATE_INVITATION_LINK_FAULT, 'CreateInvitationLink', 1)
export class CreateInvitationLinkCommand extends LiveShareCommandBase {

    constructor(
        private workspaceService: vsls.WorkspaceService
    ) {
        super();
    }

    public async invoke(linkInfo: vsls.InvitationLinkInfo, context: ICommandContext): Promise<string> {
        const { cancellationTokenSource } = context;
        context.telemetryEvent.addProperty(TelemetryPropertyNames.CREATE_INVITATION_LINK, true);
        return await this.workspaceService.createInvitationLinkAsync(linkInfo, cancellationTokenSource && cancellationTokenSource.token);
    }
}