import * as path from 'path';
import * as os from 'os';

import * as vscode from 'vscode';
import { TraceSource } from '@vs/vso-logging';

import {
    EXTENSION_ROOT_PATH,
    DOTNET_ROOT_ENVIRONMENT_VARIABLE_NAME,
    DOTNET_ROOT_X86_ENVIRONMENT_VARIABLE_NAME } from '../constants';
import { OSPlatform } from '@vs/vso-node-utils';
import { PackageManager } from '../packageManager';

/*
Class helper to implement a custom DebugAdapterExecutable instance that would pass addtional arguments
to our debug host adapter
*/
export class AdapterExecutableProvider implements vscode.DebugConfigurationProvider {
    
    // Multiple debug adapter executables can be launched in the same debug session. Each can have different
    // adapter arguments. There is a call to resolve debug configurations for each debug adapter to
    // be executed. Force debugAdapterExecutable to complete one debug configuration before setting
    // adapter arguments for the next one.
    private adapterArguments: Array<string>;
    private lastAdapterArguments: Array<string>;
    private readonly callbacks: Array<Function> = [];

    constructor(
        private debugAdapterAssembly: string,
        private trace: TraceSource) {
     }

    public debugAdapterExecutable(folder: vscode.WorkspaceFolder | undefined, token?: vscode.CancellationToken): vscode.ProviderResult<vscode.DebugAdapterExecutable> {
        let adapterBinPath = path.join(EXTENSION_ROOT_PATH, 'dotnet_modules', this.debugAdapterAssembly);
        if (os.platform() === OSPlatform.WINDOWS) {
            adapterBinPath += '.exe';
        }

        let args = this.adapterArguments;
        // If the args are undefined it is mostly because vscode is calling multiple times
        // this method without calling resolveDebugConfiguration (as the case when using 'extensionHost')
        if (args === undefined) {
            args = this.lastAdapterArguments;
        } else {
            this.lastAdapterArguments = args;
        }

        this.adapterArguments = undefined;

        // If there are multiple launch configurations
        // invoke the next callback to continue resolving
        // debug configurations
        const callback = this.callbacks.shift();
        if (callback) {
            callback();
        }

        const dotnetInstallPath = PackageManager.getDotnetInstallPath();
        const options = {
            env: {
                [`${DOTNET_ROOT_ENVIRONMENT_VARIABLE_NAME}`]: dotnetInstallPath,
                [`${DOTNET_ROOT_X86_ENVIRONMENT_VARIABLE_NAME}`]: dotnetInstallPath
            }
        };
        
        this.trace.info(`->debugAdapterExecutable path:${adapterBinPath} args:${JSON.stringify(args)}`);
        return new vscode.DebugAdapterExecutable(adapterBinPath, args, options);
    }

    // Sets adapter arguments to be used by debugAdapterExecutable.
    // Force debugAdapterExecutable to complete one debug configuration before setting
    // adapter arguments for the next one.
    public async setAdapterArguments(args: Array<string>): Promise<void> {
        this.trace.info(`->setAdapterArguments args:${JSON.stringify(args)}`);

        if (this.adapterArguments !== undefined) {
            await new Promise((resolve: Function, reject: Function) => this.callbacks.push(() => resolve()));
        }
        this.adapterArguments = args;
    }
}