export enum EventReason {
    None = 1,
    Go = 2,
    AttachProgram = 3,
    DetachProgram = 4,
    LaunchProgram = 5,
    EndProgram = 6,
    StopDebugging = 7,
    Step = 8,
    Breakpoint = 9,
    ExceptionThrown = 10,
    ExceptionNotHandled = 11,
    UserBreak = 12,
    ContextSwitch = 13
}

export interface UIDebugEvent {
    type: string;
}

export namespace DebugSourceEventTypes {
    export const debugSessionsSourceId = 'debugSessions';
    export const debugSessionAddId = 'debugSessionAdd';
    export const debugSessionRemoveId = 'debugSessionRemove';
}

export namespace UIDebugEventTypes {
    export const enterRunMode: string = 'enterRunMode';
    export const debugMessage: string = 'debugMessage';
    export const adapterInitialized = 'adapterInitialized';
}

export interface EnterRunMode extends UIDebugEvent {
    Reason: EventReason;
}

export enum DebugMessageType {
    OutputString = 1,
    MessageBox = 2,
    ReasonException = 256,
    ReasonTracepoint = 512
}

export interface DebugMessageEvent extends UIDebugEvent {
    MessageType: DebugMessageType;
    Message: string;
}

export interface DebugAdapterInitialized extends UIDebugEvent {
}
