'use strict';

import { Inittable, Disposable } from '@vs/vscode-command-framework';

import { IWorkspaceTaskClientManager } from '../abstractions/Interfaces';
import { IDependencies } from '../IDependencies';
import { WorkspaceTaskClient } from '@vs/liveshare-tasks';
import { default as streamChannelFactory } from '../../agentStreamChannelFactory';

export class WorkspaceTaskClientManager extends Inittable(Disposable(Object)) implements IWorkspaceTaskClientManager {
    private workspaceTaskClient: WorkspaceTaskClient | undefined;

    constructor(private readonly context: IDependencies) {
        super();
    }

    public async init(): Promise<void> {
        await super.init();

        this.workspaceTaskClient = new WorkspaceTaskClient(
            this.context,
            this.context.accessControlManager(),
            streamChannelFactory(this.context));
        await this.workspaceTaskClient.init();
    }

    public async dispose(): Promise<void> {
        if (this.workspaceTaskClient) {
            await this.workspaceTaskClient.dispose();
            this.workspaceTaskClient = undefined;
        }

        await super.dispose();
    }
}