import { PolicyResolutionStrategy } from './policyResolutionStrategy';

export class AnonymousGuestApprovalStrategy implements PolicyResolutionStrategy<string> {
    public readonly default: string = 'prompt';

    public resolvePolicy(policyValues: string[]): string {
        if (!policyValues || policyValues.length === 0)
            return this.default;

        if (policyValues.includes('reject'))
            return 'reject';

        if (policyValues.includes('prompt'))
            return 'prompt';

        if (policyValues.includes('accept'))
            return 'accept';

        return this.default;
    }
}
