import { IClipboard } from '../IClipboard';
import { write as copyToClipboardAsync, readSync as pasteFromClipboard } from 'clipboardy';

class NodeClipboard implements IClipboard {
    public writeAsync(value: string): Promise<void> {
        return copyToClipboardAsync(value);
    }

    public readAsync(): Promise<string> {
        return Promise.resolve(pasteFromClipboard());
    }
}

export const clipboard = new NodeClipboard();