import { ITelemetryReporterFactory } from '../ITelemetryReporterFactory';
import TelemetryReporter from 'vscode-extension-telemetry';
import { ITelemetryReporter } from '@vs/vso-telemetry';

export const telemetryReporterFactory: ITelemetryReporterFactory = {
    create: (extensionPackage: any) => {
        // Defer import of `vscode-extension-telemetry` package.
        const telemetryReporterClass: typeof TelemetryReporter = require('vscode-extension-telemetry')
            .default;

        const props = extensionPackage as { name: string; version: string; aiKey: string };
        const { name, version, aiKey } = props;

        if (!aiKey) {
            throw new Error('The `aiKey` property needs to be set in the `package.json`.');
        }

        const telemetryReporter = new telemetryReporterClass(name, version, aiKey);
        return {
            sendTelemetryEvent: (eventName, properties, measurements) => {
                telemetryReporter.sendTelemetryEvent(eventName, properties, measurements);
            },
            sendTelemetryErrorEvent: (eventName, properties, measurements, errorProps) => {
                telemetryReporter.sendTelemetryErrorEvent(
                    eventName,
                    properties,
                    measurements,
                    errorProps,
                );
            },
            dispose: () => telemetryReporter.dispose(),
        } as ITelemetryReporter;
    },
};
