import * as vscode from 'vscode';
import { TelemetryEvent } from '@vs/vso-telemetry';
import { LanguageServiceTelemetryEventNames } from '@vs/liveshare-lsp';

import {
    ExtensionUtil,
    SessionState,
    SessionStateChangedEventArgs,
    sessionStateTracker,
} from '@vs/liveshare-core';

class OpportunisticCodeLensProvider implements vscode.CodeLensProvider {

    private static readonly startSessionFromCodeLensCommand = 'liveshare.codelens.start';
    private static readonly shareCommand: vscode.Command = {
        title: 'Start Live Share Session',
        command: OpportunisticCodeLensProvider.startSessionFromCodeLensCommand
    };
    private static readonly targetCodeLenses = ['merge-conflict.accept.current'];

    private askForCodeLenses = true;
    private isCollaborating = false;

    // tslint:disable
    private _onDidChangeCodeLenses = new vscode.EventEmitter<void>();
    // tslint:enable
    public readonly onDidChangeCodeLenses = this._onDidChangeCodeLenses.event;

    private hasShown = false;

    constructor() {
        sessionStateTracker.onStateChanged(this.onStateChanged.bind(this));
        ExtensionUtil.context.subscriptions.push(ExtensionUtil.registerCommand(OpportunisticCodeLensProvider.startSessionFromCodeLensCommand, () => this.startLiveShareSession(), this));
    }

    private async startLiveShareSession(): Promise<void> {
        (new TelemetryEvent(LanguageServiceTelemetryEventNames.INVOKE_OPPORTUNISTIC_CODE_LENS)).send();
        await vscode.commands.executeCommand('liveshare.start');
    }

    private onStateChanged(e: SessionStateChangedEventArgs): void {
        const nowCollaborating = [SessionState.Shared, SessionState.Joined].indexOf(e.newState) >= 0;
        if (this.isCollaborating !== nowCollaborating) {
            this.isCollaborating = nowCollaborating;
            this._onDidChangeCodeLenses.fire();
        }
    }

    private createCodeLens(range: vscode.Range): vscode.CodeLens {
        if (!this.hasShown) {
            (new TelemetryEvent(LanguageServiceTelemetryEventNames.SHOW_OPPORTUNISTIC_CODE_LENS)).send();
            this.hasShown = true;
        }
        return new vscode.CodeLens(range, OpportunisticCodeLensProvider.shareCommand);
    }

    public async provideCodeLenses(document: vscode.TextDocument, cancellationToken: vscode.CancellationToken): Promise<vscode.CodeLens[]> {
        if (this.isCollaborating) {
            return [];
        }
        /// This CodeLens is recursive - it needs to request all other CodeLenses to compute (vscode.executeCodeLensProvider), and requesting 
        /// all other CodeLenses will result in this method being called. The askForCodeLenses variable is used to provide the base case.
        /// Before asking for all CodeLenses, askForCodeLenses is set to false so that when this method is called again, it doesn't make
        /// yet another recursive call, but instead returns no CodeLenses.
        if (!this.askForCodeLenses) {
            this.askForCodeLenses = true;
            return [];
        } else {
            let opportunisticCodeLenses: vscode.CodeLens[] = [];
            this.askForCodeLenses = false;
            let otherCodeLenses: vscode.CodeLens[] = await vscode.commands.executeCommand<vscode.CodeLens[]>('vscode.executeCodeLensProvider', document.uri, 0);
            if (otherCodeLenses) {
                for (let cl of otherCodeLenses) {
                    if (cl.command && OpportunisticCodeLensProvider.targetCodeLenses.indexOf(cl.command.command) >= 0) {
                        opportunisticCodeLenses.push(this.createCodeLens(cl.range));
                    }
                }
            }
            return opportunisticCodeLenses;
        }
    }

}

export function registerCodeLensProvider() {
    ExtensionUtil.context.subscriptions.push(vscode.languages.registerCodeLensProvider('*', new OpportunisticCodeLensProvider()));
}
